#pragma once
#include <JuceHeader.h>
#include "DSP/GlitchEngine.h"
#include "DSP/DiffusionNetwork.h"
#include "DSP/PitchDrifter.h"
#include "DSP/StereoWidener.h"

class AlienMachineProcessor : public juce::AudioProcessor
{
public:
    AlienMachineProcessor();
    ~AlienMachineProcessor() override = default;

    //==========================================================================
    // Standard JUCE plugin lifecycle callbacks
    //==========================================================================
    void prepareToPlay(double sampleRate, int samplesPerBlock) override;
    void releaseResources() override {}
    void processBlock(juce::AudioBuffer<float>&, juce::MidiBuffer&) override;

    //==========================================================================
    // Host queries
    //==========================================================================
    juce::AudioProcessorEditor* createEditor() override;
    bool hasEditor() const override { return true; }
    const juce::String getName() const override { return "Alien Machine"; }
    bool acceptsMidi() const override { return false; }
    bool producesMidi() const override { return false; }
    double getTailLengthSeconds() const override { return 4.0; }
    int getNumPrograms() override { return 1; }
    int getCurrentProgram() override { return 0; }
    void setCurrentProgram(int) override {}
    const juce::String getProgramName(int) override { return "Default"; }
    void changeProgramName(int, const juce::String&) override {}
    void getStateInformation(juce::MemoryBlock&) override {}
    void setStateInformation(const void*, int) override {}

    bool isBusesLayoutSupported(const BusesLayout& layouts) const override;

    //==========================================================================
    // APVTS — AudioProcessorValueTreeState manages parameter storage,
    // thread-safe access, and undo/redo automatically.
    //==========================================================================
    juce::AudioProcessorValueTreeState apvts;

private:
    //==========================================================================
    // DSP stage objects (one instance each, initialized in prepareToPlay)
    //==========================================================================
    GlitchEngine      glitchEngine;
    DiffusionNetwork  diffusionNetwork;
    PitchDrifter      pitchDrifter;
    StereoWidener     stereoWidener;

    //==========================================================================
    // Feedback state: two samples (L and R) held between processBlock calls.
    // The feedback loop spans across blocks, so we persist it as member state.
    //==========================================================================
    float feedbackL = 0.0f;
    float feedbackR = 0.0f;

    // One-pole LPF state for the feedback path (fixed ~8kHz cutoff)
    float fbLpfStateL = 0.0f;
    float fbLpfStateR = 0.0f;
    float fbLpfCoeff  = 0.0f;  // calculated in prepareToPlay

    //==========================================================================
    // SmoothedValues prevent zipper noise when parameters change mid-block.
    // They ramp smoothly from old value to new value over ~20ms.
    //==========================================================================
    juce::SmoothedValue<float> morphSmoothed;
    juce::SmoothedValue<float> mixSmoothed;
    juce::SmoothedValue<float> feedbackSmoothed;

    // Factory function required by APVTS constructor
    static juce::AudioProcessorValueTreeState::ParameterLayout createParameterLayout();

    JUCE_DECLARE_NON_COPYABLE_WITH_LEAK_DETECTOR(AlienMachineProcessor)
};

# Cog VST Implementation Plan

> **For agentic workers:** REQUIRED SUB-SKILL: Use superpowers:subagent-driven-development (recommended) or superpowers:executing-plans to implement this plan task-by-task. Steps use checkbox (`- [ ]`) syntax for tracking.

**Goal:** Build Cog VST — a psychedelic sound design module (VST3/AU/Standalone) with texture/body parallel path architecture, spectral drone engine, self-resonating filters, 3-stage drive, feedback loop, stereo widener, and self-evolving modulation system.

**Architecture:** Parallel-path effect plugin. Input splits into texture (waveshaper) and body (spectral drone + chorus) via envelope-based detection. Paths merge into self-resonating filters → drive → feedback loop → stereo widener → limiter. 3 cross-modulating LFOs + audio-reactive modulation provide evolving movement. 26 parameters, 18-20 presets, ~42ms reported latency.

**Tech Stack:** JUCE 7.0.12, C++17, CMake 3.22+, VST3 + AU + Standalone

**Spec:** `docs/superpowers/specs/2026-03-28-cog-vst-design.md`

**Project Directory:** `/home/myuser/CogVST/`

---

