- [ ] **Step 1: Write FastMath.h**

```cpp
#pragma once
#include <cmath>

namespace CogDSP {

// Padé approximant tanh — error < 0.1% for |x| < 4
// For |x| >= 4, returns ±1.0
inline float fastTanh(float x)
{
    if (x > 4.0f) return 1.0f;
    if (x < -4.0f) return -1.0f;
    float x2 = x * x;
    return x * (27.0f + x2) / (27.0f + 9.0f * x2);
}

// Fast atan — polynomial for |x| < 2.5, asymptotic beyond
inline float fastAtan(float x)
{
    if (x > 2.5f) return 1.5707963f - 1.0f / x;    // pi/2 - 1/x
    if (x < -2.5f) return -1.5707963f - 1.0f / x;
    float x2 = x * x;
    return x * (1.0f + 0.28125f * x2) / (1.0f + 0.5625f * x2 + 0.078125f * x2 * x2);
}

// Fast exp(-x*x) — rational approximation
inline float fastGaussian(float x)
{
    float x2 = x * x;
    return 1.0f / (1.0f + x2 * (1.0f + x2 * 0.5f));
}

} // namespace CogDSP
```

- [ ] **Step 2: Write DCBlocker.h**

```cpp
#pragma once

namespace CogDSP {

class DCBlocker
{
public:
    void prepare(double sampleRate)
    {
        // 5Hz HPF cutoff, scaled by sample rate
        R = 1.0f - static_cast<float>(2.0 * 3.14159265358979 * 5.0 / sampleRate);
    }

    void reset()
    {
        xPrev = 0.0f;
        yPrev = 0.0f;
    }

    float process(float x)
    {
        float y = x - xPrev + R * yPrev;
        xPrev = x;
        yPrev = y;
        return y;
    }

private:
    float R = 0.99935f;
    float xPrev = 0.0f;
    float yPrev = 0.0f;
};

} // namespace CogDSP
```

- [ ] **Step 3: Write DelayLine.h**

```cpp
#pragma once
#include <vector>
#include <algorithm>
#include <cstring>

namespace CogDSP {

class DelayLine
{
public:
    void prepare(int maxSamples)
    {
        // Round up to power of 2 for & mask wrapping
        int size = 1;
        while (size < maxSamples + 1) size <<= 1;
        buffer.resize(size, 0.0f);
        mask = size - 1;
        writePos = 0;
    }

    void reset()
    {
        std::fill(buffer.begin(), buffer.end(), 0.0f);
        writePos = 0;
    }

    void write(float sample)
    {
        buffer[writePos & mask] = sample;
        ++writePos;
    }

    // Read at integer delay (samples ago)
    float read(int delaySamples) const
    {
        return buffer[(writePos - delaySamples) & mask];
    }

    // Read with fractional delay (linear interpolation)
    float readInterp(float delaySamples) const
    {
        int d0 = static_cast<int>(delaySamples);
        float frac = delaySamples - static_cast<float>(d0);
        float s0 = buffer[(writePos - d0) & mask];
        float s1 = buffer[(writePos - d0 - 1) & mask];
        return s0 + frac * (s1 - s0);
    }

private:
    std::vector<float> buffer;
    int mask = 0;
    int writePos = 0;
};

} // namespace CogDSP
```

