84	    diffusionNetwork.prepare(sr, spb);
85	    pitchDrifter.prepare(sr, spb);
86	    inputDetector.prepare(sr, spb);
87	    filterDetector.prepare(sr, spb);
88	    dualFilter.prepare(sr, spb);
89	
90	    dryBuffer.setSize(2, spb);
91	    glitchInputBuffer.setSize(2, spb);
92	    cleanPassBuffer.setSize(2, spb);
93	    wetBuffer.setSize(2, spb);
94	    filteredBuffer.setSize(2, spb);
95	    processedBuffer.setSize(2, spb);
96	    feedbackBuffer.setSize(2, spb);
97	    feedbackBuffer.clear();
98	
99	    const double sm = 0.02; // 20 ms ramp for most params
