116	//==============================================================================
117	void EpiphanyMachineProcessor::processBlock(juce::AudioBuffer<float>& buffer,
118	                                             juce::MidiBuffer&)
119	{
120	    juce::ScopedNoDenormals noDenormals;
121	    const int N = buffer.getNumSamples();
122	
123	    if (buffer.getNumChannels() == 1)
124	        buffer.copyFrom(1, 0, buffer, 0, 0, N);
125	
126	    dryBuffer.copyFrom(0, 0, buffer, 0, 0, N);
127	    dryBuffer.copyFrom(1, 0, buffer, 1, 0, N);
128	
129	    auto getV = [&](const char* id) { return apvts.getRawParameterValue(id)->load(); };
130	
131	    const bool  isBypassed   = getV("bypass") > 0.5f;
132	    const bool  isFrozen     = getV("freeze") > 0.5f;
133	    const int   filterPos    = (int)getV("filterPos");
134	    const int   presetIdx    = (int)getV("preset");
135	    const float morphTimeSec = getV("morphTime");
136	
137	    bypassSmoothed.setTargetValue(isBypassed ? 1.0f : 0.0f);
138	    morphSmoothed.setTargetValue(getV("morph"));
139	    mixSmoothed.setTargetValue(getV("mix"));
140	    feedbackSmoothed.setTargetValue(getV("feedback"));
141	    glitchFocusSmoothed.setTargetValue(getV("glitchFocus"));
142	    driveSmoothed.setTargetValue(getV("drive"));
143	
144	    glitchEngine.setDensity(getV("density"));
145	    glitchEngine.setChaos(getV("chaos"));
146	    glitchEngine.setDrift(getV("drift"));
147	    diffusionNetwork.setDecaySeconds(getV("decay"));
148	    diffusionNetwork.setDamping(getV("damping"));
149	    diffusionNetwork.setWidth(getV("width"));
150	    diffusionNetwork.setFreezeActive(isFrozen);
151	    pitchDrifter.setDrift(getV("drift"));
152	    inputDetector.setSensitivity(getV("sensitivity"));
153	    filterDetector.setSensitivity(getV("sensitivity"));
154	    dualFilter.setTexFilterType((int)getV("texFilterType"));
155	    dualFilter.setTexCutoff(getV("texFilterCutoff"));
156	    dualFilter.setTexReso(getV("texFilterReso"));
157	    dualFilter.setTexLfoRate(getV("texLfoRate"));
158	    dualFilter.setTexLfoDepth(getV("texLfoDepth"));
159	    dualFilter.setBodyFilterType((int)getV("bodyFilterType"));
160	    dualFilter.setBodyCutoff(getV("bodyFilterCutoff"));
161	    dualFilter.setBodyReso(getV("bodyFilterReso"));
162	
163	    if (presetIdx != lastPresetIdx) {
164	        presetManager.selectPreset(presetIdx, morphTimeSec);
165	        lastPresetIdx = presetIdx;
166	    }
167	    presetManager.advance(getSampleRate(), N);
168	
169	    //--- Fast bypass ---
170	    if (bypassSmoothed.getCurrentValue() >= 0.999f && isBypassed)
171	    {
172	        for (int i = 0; i < N; ++i) {
173	            morphSmoothed.getNextValue(); mixSmoothed.getNextValue();
174	            feedbackSmoothed.getNextValue(); glitchFocusSmoothed.getNextValue();
175	            driveSmoothed.getNextValue(); bypassSmoothed.getNextValue();
176	        }
177	        buffer.copyFrom(0, 0, dryBuffer, 0, 0, N);
178	        buffer.copyFrom(1, 0, dryBuffer, 1, 0, N);
179	        return;
180	    }
181	
182	    //--- Step 1: Input detect ---
183	    inputDetector.process(buffer, N);
184	    const auto& texBuf = inputDetector.getTextureBuffer();
185	    const auto& bodBuf = inputDetector.getBodyBuffer();
186	
187	    //--- Step 2: Glitch focus routing ---
188	    {
189	        auto* giL = glitchInputBuffer.getWritePointer(0);
190	        auto* giR = glitchInputBuffer.getWritePointer(1);
191	        auto* cpL = cleanPassBuffer.getWritePointer(0);
192	        auto* cpR = cleanPassBuffer.getWritePointer(1);
193	        const auto* inL = buffer.getReadPointer(0);
194	        const auto* inR = buffer.getReadPointer(1);
195	        const auto* tL  = texBuf.getReadPointer(0);
196	        const auto* tR  = texBuf.getReadPointer(1);
197	        const auto* bL  = bodBuf.getReadPointer(0);
198	        const auto* bR  = bodBuf.getReadPointer(1);
199	        for (int i = 0; i < N; ++i)
200	        {
201	            const float gf = glitchFocusSmoothed.getNextValue();
202	            if (gf <= 0.5f) {
203	                float t = gf * 2.0f;
204	                giL[i] = bL[i]*(1.0f-t) + inL[i]*t; giR[i] = bR[i]*(1.0f-t) + inR[i]*t;
205	                cpL[i] = tL[i]*(1.0f-t);             cpR[i] = tR[i]*(1.0f-t);
206	            } else {
207	                float t = (gf-0.5f)*2.0f;
208	                giL[i] = inL[i]*(1.0f-t) + tL[i]*t; giR[i] = inR[i]*(1.0f-t) + tR[i]*t;
209	                cpL[i] = bL[i]*t;                     cpR[i] = bR[i]*t;
210	            }
211	        }
212	    }
213	
214	    //--- Step 3: Glitch Engine ---
215	    glitchEngine.process(glitchInputBuffer);
216	
217	    //--- Step 4: Morph blend + add full-block feedback from previous block ---
218	    {
219	        auto* outL = buffer.getWritePointer(0);
220	        auto* outR = buffer.getWritePointer(1);
221	        const auto* giL = glitchInputBuffer.getReadPointer(0);
222	        const auto* giR = glitchInputBuffer.getReadPointer(1);
223	        const auto* cpL = cleanPassBuffer.getReadPointer(0);
224	        const auto* cpR = cleanPassBuffer.getReadPointer(1);
225	        const auto* fbL = feedbackBuffer.getReadPointer(0);
226	        const auto* fbR = feedbackBuffer.getReadPointer(1);
227	        for (int i = 0; i < N; ++i)
228	        {
229	            const float morph = morphSmoothed.getNextValue();
230	            feedbackSmoothed.getNextValue();  // advance, read via getCurrentValue() later
231	            driveSmoothed.getNextValue();     // advance, read via getCurrentValue() in Step 10
232	            outL[i] = cpL[i] + giL[i] * morph + fbL[i];
233	            outR[i] = cpR[i] + giR[i] * morph + fbR[i];
234	        }
235	    }
236	
237	    //--- Step 5: DiffusionNetwork ---
238	    diffusionNetwork.process(buffer);
239	    wetBuffer.copyFrom(0, 0, buffer, 0, 0, N);
240	    wetBuffer.copyFrom(1, 0, buffer, 1, 0, N);
241	
242	    //--- Step 6: Filter in WET position ---
243	    if (filterPos == 1)
244	    {
245	        filterDetector.process(wetBuffer, N);
246	        dualFilter.process(filterDetector.getTextureBuffer(),
247	                           filterDetector.getBodyBuffer(), wetBuffer, N);
248	    }
249	
250	    //--- Step 7: Dry/Wet MIX + Bypass blend ---
251	    {
252	        auto* outL = buffer.getWritePointer(0);
253	        auto* outR = buffer.getWritePointer(1);
254	        const auto* dryL = dryBuffer.getReadPointer(0);
255	        const auto* dryR = dryBuffer.getReadPointer(1);
256	        const auto* wetL = wetBuffer.getReadPointer(0);
257	        const auto* wetR = wetBuffer.getReadPointer(1);
258	        for (int i = 0; i < N; ++i)
259	        {
260	            const float mix      = mixSmoothed.getNextValue();
261	            const float bypassed = bypassSmoothed.getNextValue();
262	            // Equal-power mixing: keeps perceived level constant as mix sweeps 0→1
263	            const float dryGain  = std::cos(mix * juce::MathConstants<float>::halfPi);
264	            const float wetGain  = std::sin(mix * juce::MathConstants<float>::halfPi);
265	            float procL = dryL[i]*dryGain + wetL[i]*wetGain;
266	            float procR = dryR[i]*dryGain + wetR[i]*wetGain;
267	            outL[i] = dryL[i]*bypassed + procL*(1.0f-bypassed);
268	            outR[i] = dryR[i]*bypassed + procR*(1.0f-bypassed);
269	            processedBuffer.setSample(0, i, procL);
270	            processedBuffer.setSample(1, i, procR);
271	        }
272	    }
273	
274	    //--- Step 8: Filter in FINAL position ---
275	    if (filterPos == 2)
276	    {
277	        filterDetector.process(processedBuffer, N);
278	        dualFilter.process(filterDetector.getTextureBuffer(),
279	                           filterDetector.getBodyBuffer(), filteredBuffer, N);
280	        auto* outL = buffer.getWritePointer(0);
281	        auto* outR = buffer.getWritePointer(1);
282	        const auto* dryL  = dryBuffer.getReadPointer(0);
283	        const auto* dryR  = dryBuffer.getReadPointer(1);
284	        const auto* filtL = filteredBuffer.getReadPointer(0);
285	        const auto* filtR = filteredBuffer.getReadPointer(1);
286	        // Use block-constant bypass gain (smoother already advanced in Step 7); acceptable 1-block transition approximation
287	        const float bypassGain = bypassSmoothed.getCurrentValue();
288	        for (int i = 0; i < N; ++i)
289	        {
290	            outL[i] = dryL[i]*bypassGain + filtL[i]*(1.0f-bypassGain);
291	            outR[i] = dryR[i]*bypassGain + filtR[i]*(1.0f-bypassGain);
292	        }
293	    }
294	
295	    //--- Step 9: tanh output limiter ---
296	    {
297	        auto* outL = buffer.getWritePointer(0);
298	        auto* outR = buffer.getWritePointer(1);
299	        for (int i = 0; i < N; ++i)
300	        {
301	            outL[i] = std::tanh(outL[i]);
302	            outR[i] = std::tanh(outR[i]);
303	        }
304	    }
305	
306	    //--- Step 10: Compute new feedbackBuffer for next block ---
307	    {
308	        const float fbGain = feedbackSmoothed.getCurrentValue();
309	        const auto* wL = wetBuffer.getReadPointer(0);
310	        const auto* wR = wetBuffer.getReadPointer(1);
311	        auto* fbL = feedbackBuffer.getWritePointer(0);
312	        auto* fbR = feedbackBuffer.getWritePointer(1);
313	        for (int i = 0; i < N; ++i)
314	        {
315	            fbL[i] = wL[i] * fbGain;
316	            fbR[i] = wR[i] * fbGain;
317	        }
318	
319	        // PitchDrifter operates in feedback loop
320	        pitchDrifter.process(feedbackBuffer);
321	
322	        // Optional filter in feedback loop
323	        if (filterPos == 3)
324	        {
325	            filterDetector.process(feedbackBuffer, N);
326	            dualFilter.process(filterDetector.getTextureBuffer(),
327	                               filterDetector.getBodyBuffer(), feedbackBuffer, N);
328	        }
329	
330	        // Wavefolder (true bypass at drive=0)
331	        const float drive = driveSmoothed.getCurrentValue();
332	        if (drive > 0.001f)
333	        {
334	            const float foldAmt = 1.0f + drive * 4.0f;
335	            const float piC     = juce::MathConstants<float>::pi;
336	            auto* fL = feedbackBuffer.getWritePointer(0);
337	            auto* fR = feedbackBuffer.getWritePointer(1);
338	            for (int i = 0; i < N; ++i)
339	            {
340	                float fx = fL[i] * foldAmt * piC;
341	                fL[i]    = fL[i] + drive * (std::sin(fx) / foldAmt - fL[i]);
342	                fx       = fR[i] * foldAmt * piC;
343	                fR[i]    = fR[i] + drive * (std::sin(fx) / foldAmt - fR[i]);
344	            }
345	        }
346	
347	        // Soft-clip feedback to prevent runaway at high feedback+drive (applied unconditionally, including freeze mode)
348	        {
349	            auto* fL = feedbackBuffer.getWritePointer(0);
350	            auto* fR = feedbackBuffer.getWritePointer(1);
351	            for (int i = 0; i < N; ++i)
352	            {
353	                fL[i] = fL[i] / (1.0f + std::abs(fL[i]));
354	                fR[i] = fR[i] / (1.0f + std::abs(fR[i]));
355	            }
356	        }
357	    }
358	}
