573	void TextureBodyDetector::EnvelopeFollower::prepare(double sampleRate, float attackMs, float releaseMs)
574	{
575	    attackCoeff = 1.0f - std::exp(-1.0f / (static_cast<float>(sampleRate) * attackMs * 0.001f));
576	    releaseCoeff = 1.0f - std::exp(-1.0f / (static_cast<float>(sampleRate) * releaseMs * 0.001f));
577	    envelope = 0.0f;
578	}
579	
580	float TextureBodyDetector::EnvelopeFollower::process(float input)
581	{
582	    float absInput = std::fabs(input);
583	    float coeff = (absInput > envelope) ? attackCoeff : releaseCoeff;
584	    envelope += coeff * (absInput - envelope);
585	    return envelope;
586	}
