588	void TextureBodyDetector::prepare(double sampleRate, int /*samplesPerBlock*/)
589	{
590	    currentSampleRate = sampleRate;
591	
592	    // Fast: 2ms attack / 80ms release
593	    fastEnvL.prepare(sampleRate, 2.0f, 80.0f);
594	    fastEnvR.prepare(sampleRate, 2.0f, 80.0f);
595	
596	    // Slow: 80ms attack / 400ms release
597	    slowEnvL.prepare(sampleRate, 80.0f, 400.0f);
598	    slowEnvR.prepare(sampleRate, 80.0f, 400.0f);
599	
600	    // 5ms smoothing coefficient
601	    smoothingCoeff = 1.0f - std::exp(-1.0f / (static_cast<float>(sampleRate) * 0.005f));
602	    smoothedCoeff = 0.0f;
603	
604	    // Spectral flux buffers
605	    fftInput.resize(fftSize * 2, 0.0f);
606	    fftOutput.resize(fftSize * 2, 0.0f);
607	    prevMagnitudes.resize(fftSize / 2, 0.0f);
608	    fftWritePos = 0;
609	    spectralFlux = 0.0f;
610	}
