612	void TextureBodyDetector::reset()
613	{
614	    fastEnvL.envelope = 0.0f; fastEnvR.envelope = 0.0f;
615	    slowEnvL.envelope = 0.0f; slowEnvR.envelope = 0.0f;
616	    smoothedCoeff = 0.0f;
617	    std::fill(fftInput.begin(), fftInput.end(), 0.0f);
618	    std::fill(prevMagnitudes.begin(), prevMagnitudes.end(), 0.0f);
619	    fftWritePos = 0;
620	    spectralFlux = 0.0f;
621	}
