623	float TextureBodyDetector::processSample(float inputL, float inputR, float sensitivity)
624	{
625	    float fastL = fastEnvL.process(inputL);
626	    float fastR = fastEnvR.process(inputR);
627	    float slowL = slowEnvL.process(inputL);
628	    float slowR = slowEnvR.process(inputR);
629	
630	    // Average channels
631	    float fast = (fastL + fastR) * 0.5f;
632	    float slow = (slowL + slowR) * 0.5f;
633	
634	    // Texture = fast - slow, scaled by sensitivity (1-8x)
635	    float sensGain = 1.0f + sensitivity * 7.0f;
636	    float rawCoeff = std::clamp((fast - slow) * sensGain, 0.0f, 1.0f);
637	
638	    // Smooth to prevent AM artifacts
639	    smoothedCoeff += smoothingCoeff * (rawCoeff - smoothedCoeff);
640	
641	    // Update spectral flux (non-routing modulation source)
642	    float mono = (inputL + inputR) * 0.5f;
643	    processSpectralFlux(mono);
644	
645	    return smoothedCoeff;
646	}
647	
648	void TextureBodyDetector::processSpectralFlux(float monoSample)
649	{
650	    fftInput[fftWritePos] = monoSample;
651	    fftWritePos++;
652	
653	    if (fftWritePos >= fftSize)
654	    {
655	        fftWritePos = 0;
656	
657	        // Copy to output buffer for in-place FFT
658	        std::copy(fftInput.begin(), fftInput.begin() + fftSize, fftOutput.begin());
659	        std::fill(fftOutput.begin() + fftSize, fftOutput.end(), 0.0f);
660	
661	        fft.performRealOnlyForwardTransform(fftOutput.data());
662	
663	        // Compute flux = sum of positive magnitude changes
664	        float flux = 0.0f;
665	        int numBins = fftSize / 2;
666	        for (int i = 0; i < numBins; ++i)
667	        {
668	            float re = fftOutput[i * 2];
669	            float im = fftOutput[i * 2 + 1];
670	            float mag = std::sqrt(re * re + im * im);
671	            float diff = mag - prevMagnitudes[i];
672	            if (diff > 0.0f) flux += diff;
673	            prevMagnitudes[i] = mag;
674	        }
675	
676	        // Normalize by number of bins
677	        spectralFlux = flux / static_cast<float>(numBins);
678	    }
679	}
