748	void Waveshaper::prepare(double sampleRate, int spectralEngineLatencySamples)
749	{
750	    dcBlockerL.prepare(sampleRate);
751	    dcBlockerR.prepare(sampleRate);
752	    dcBlockerL.reset();
753	    dcBlockerR.reset();
754	
755	    latencyCompSamples = spectralEngineLatencySamples;
756	    delayL.prepare(spectralEngineLatencySamples + 64);
757	    delayR.prepare(spectralEngineLatencySamples + 64);
758	    delayL.reset();
