770	float Waveshaper::processSample(float input, float drive)
771	{
772	    // Bypass at zero
773	    if (drive < 0.001f)
774	        return input;
775	
776	    // Soft curve: tanh — warm, even harmonics
777	    float softGain = 1.0f + drive * 3.0f;
778	    float soft = fastTanh(input * softGain);
779	
780	    // Hard curve: atan — asymmetric, odd+even harmonics, bounded
781	    float hardGain = 1.0f + drive * 8.0f;
782	    float hard = (2.0f / 3.14159265f) * fastAtan(input * hardGain);
783	
784	    // Crossfade: low drive = soft, high drive = hard
785	    float t = std::clamp(drive * 2.0f - 1.0f, 0.0f, 1.0f); // 0-0.5 = soft, 0.5-1 = blend to hard
786	    float shaped;
787	    if (drive <= 0.5f)
788	        shaped = soft;
789	    else
790	        shaped = soft * (1.0f - t) + hard * t;
791	
792	    // Blend with dry based on drive amount
793	    return input + drive * (shaped - input);
794	}
