796	void Waveshaper::process(juce::AudioBuffer<float>& buffer, float textureDrive)
797	{
798	    auto* left = buffer.getWritePointer(0);
799	    auto* right = buffer.getWritePointer(1);
800	    int numSamples = buffer.getNumSamples();
801	
802	    for (int i = 0; i < numSamples; ++i)
803	    {
804	        // Buffer already scaled by texture coefficient at split stage — no double-scaling
805	        float outL = processSample(left[i], textureDrive);
806	        float outR = processSample(right[i], textureDrive);
807	
808	        // DC block
809	        outL = dcBlockerL.process(outL);
810	        outR = dcBlockerR.process(outR);
811	
812	        // Write to latency compensation delay
813	        delayL.write(outL);
814	        delayR.write(outR);
815	
816	        // Store compensated output back (for later merge read)
817	        left[i] = outL;
818	        right[i] = outR;
819	    }
820	}
