931	void SpectralDroneEngine::prepare(double hostSampleRate, int /*samplesPerBlock*/)
932	{
933	    hostRate = hostSampleRate;
934	
935	    // Compute decimation factor (target ~48kHz internal)
936	    if (hostSampleRate > 96000.0)
937	        decimationFactor = static_cast<int>(std::round(hostSampleRate / 48000.0));
938	    else if (hostSampleRate > 48000.0)
939	        decimationFactor = 2;
940	    else
941	        decimationFactor = 1;
942	
943	    // Anti-alias filter at 20kHz (before decimation)
944	    if (decimationFactor > 1)
945	    {
946	        computeButterworthLP(antiAliasL, hostSampleRate, 20000.0);
947	        computeButterworthLP(antiAliasR, hostSampleRate, 20000.0);
948	        computeButterworthLP(antiImageL, hostSampleRate, 20000.0);
949	        computeButterworthLP(antiImageR, hostSampleRate, 20000.0);
950	    }
951	
952	    // Freeze smoothing: ~50ms at internal rate
953	    double internalRate = hostSampleRate / decimationFactor;
954	    freezeSmoothCoeff = 1.0f - std::exp(-1.0f / (static_cast<float>(internalRate) * 0.05f));
955	
956	    precomputeWindow();
957	    reset();
958	}
