982	void SpectralDroneEngine::precomputeWindow()
983	{
984	    for (int i = 0; i < fftSize; ++i)
985	        buffers.window[i] = 0.5f * (1.0f - std::cos(2.0f * 3.14159265f * i / fftSize));
