988	void SpectralDroneEngine::computeButterworthLP(BiquadState& state, double sampleRate, double cutoff)
989	{
990	    double w0 = 2.0 * 3.14159265358979 * cutoff / sampleRate;
991	    double cosw0 = std::cos(w0);
992	    double sinw0 = std::sin(w0);
993	    double alpha = sinw0 / (2.0 * 0.7071067811865476); // Q = sqrt(2)/2 for Butterworth
994	
995	    double a0 = 1.0 + alpha;
996	    state.b0 = static_cast<float>((1.0 - cosw0) / 2.0 / a0);
997	    state.b1 = static_cast<float>((1.0 - cosw0) / a0);
998	    state.b2 = state.b0;
999	    state.a1 = static_cast<float>(-2.0 * cosw0 / a0);
1000	    state.a2 = static_cast<float>((1.0 - alpha) / a0);
1001	    state.x1 = state.x2 = state.y1 = state.y2 = 0.0f;
1002	}
1003	
1004	float SpectralDroneEngine::processBiquad(BiquadState& s, float input)
1005	{
1006	    float output = s.b0 * input + s.b1 * s.x1 + s.b2 * s.x2 - s.a1 * s.y1 - s.a2 * s.y2;
1007	    s.x2 = s.x1; s.x1 = input;
1008	    s.y2 = s.y1; s.y1 = output;
1009	    return output;
1010	}
