1012	void SpectralDroneEngine::processHop(float droneDensity, float spectralDrift, bool freeze)
1013	{
1014	    // Smooth freeze transition
1015	    freezeTarget = freeze ? 1.0f : 0.0f;
1016	    freezeGain += freezeSmoothCoeff * (freezeTarget - freezeGain);
1017	
1018	    // Effective blend coefficient
1019	    float blendCoeff = std::max(droneDensity, freezeGain);
1020	
1021	    // Window the input and copy to workspace
1022	    for (int i = 0; i < fftSize; ++i)
1023	    {
1024	        int readIdx = (inputWritePos - fftSize + i + fftSize * 2) % (fftSize);
1025	        buffers.fftWorkspace[i] = buffers.inputRing[readIdx] * buffers.window[i];
1026	    }
1027	    std::fill(buffers.fftWorkspace + fftSize, buffers.fftWorkspace + fftSize * 2, 0.0f);
1028	
1029	    // Forward FFT
1030	    fft.performRealOnlyForwardTransform(buffers.fftWorkspace);
1031	
1032	    // Spectral processing: blend with previous frame (branch-free)
1033	    float oneMinusBlend = 1.0f - blendCoeff;
1034	    for (int bin = 0; bin < numBins; ++bin)
1035	    {
1036	        float re = buffers.fftWorkspace[bin * 2];
1037	        float im = buffers.fftWorkspace[bin * 2 + 1];
1038	
1039	        re = re * oneMinusBlend + buffers.prevFrameRe[bin] * blendCoeff;
1040	        im = im * oneMinusBlend + buffers.prevFrameIm[bin] * blendCoeff;
1041	
1042	        buffers.prevFrameRe[bin] = re;
1043	        buffers.prevFrameIm[bin] = im;
1044	
1045	        buffers.fftWorkspace[bin * 2] = re;
1046	        buffers.fftWorkspace[bin * 2 + 1] = im;
1047	    }
1048	
1049	    // Spectral drift: rotate bins (skip if frozen or drift near zero)
1050	    if (std::fabs(spectralDrift) > 0.001f && freezeGain < 0.99f)
1051	    {
1052	        float shiftBins = spectralDrift * 10.0f; // ±10 bins at full drift
1053	        int shiftInt = static_cast<int>(shiftBins);
1054	        float shiftFrac = shiftBins - static_cast<float>(shiftInt);
1055	
1056	        // Use pre-allocated member buffers (avoids ~8KB stack alloc in audio thread)
1057	        std::memset(buffers.driftTempRe, 0, sizeof(float) * numBins);
1058	        std::memset(buffers.driftTempIm, 0, sizeof(float) * numBins);
1059	
1060	        for (int bin = 0; bin < numBins; ++bin)
1061	        {
1062	            int srcBin = bin - shiftInt;
1063	            int srcBin2 = srcBin - 1;
1064	
1065	            if (srcBin >= 0 && srcBin < numBins && srcBin2 >= 0 && srcBin2 < numBins)
1066	            {
1067	                float frac = (shiftBins >= 0.0f) ? shiftFrac : -shiftFrac;
1068	                buffers.driftTempRe[bin] = buffers.fftWorkspace[srcBin * 2] * (1.0f - frac)
1069	                                         + buffers.fftWorkspace[srcBin2 * 2] * frac;
1070	                buffers.driftTempIm[bin] = buffers.fftWorkspace[srcBin * 2 + 1] * (1.0f - frac)
1071	                                         + buffers.fftWorkspace[srcBin2 * 2 + 1] * frac;
1072	            }
1073	        }
1074	
1075	        for (int bin = 0; bin < numBins; ++bin)
1076	        {
1077	            buffers.fftWorkspace[bin * 2] = buffers.driftTempRe[bin];
1078	            buffers.fftWorkspace[bin * 2 + 1] = buffers.driftTempIm[bin];
1079	        }
1080	    }
1081	
1082	    // Inverse FFT
1083	    fft.performRealOnlyInverseTransform(buffers.fftWorkspace);
1084	
1085	    // Overlap-add to output buffer
1086	    for (int i = 0; i < fftSize; ++i)
1087	    {
1088	        int outIdx = (outputReadPos + i) % fftSize;
1089	        if (firstHopDone)
1090	            buffers.outputOverlap[outIdx] += buffers.fftWorkspace[i] * buffers.window[i];
1091	        else
1092	            buffers.outputOverlap[outIdx] = buffers.fftWorkspace[i] * buffers.window[i];
1093	    }
1094	
1095	    firstHopDone = true;
1096	}
1097	
1098	void SpectralDroneEngine::process(const juce::AudioBuffer<float>& input,
1099	                                   juce::AudioBuffer<float>& output,
1100	                                   float droneDensity,
1101	                                   float spectralDrift,
1102	                                   bool freeze)
1103	{
1104	    auto* inL = input.getReadPointer(0);
1105	    auto* inR = input.getReadPointer(1);
1106	    auto* outL = output.getWritePointer(0);
1107	    auto* outR = output.getWritePointer(1);
1108	    int numSamples = input.getNumSamples();
1109	
1110	    // decimCount is a member variable — persists across processBlock calls
1111	    int outSample = 0;
1112	
1113	    for (int i = 0; i < numSamples; ++i)
1114	    {
1115	        float monoIn;
1116	        if (decimationFactor > 1)
1117	        {
1118	            // Anti-alias filter
1119	            float filtL = processBiquad(antiAliasL, inL[i]);
1120	            float filtR = processBiquad(antiAliasR, inR[i]);
1121	            monoIn = (filtL + filtR) * 0.5f;
1122	
1123	            // Decimation: only process every N-th sample
1124	            decimCount++;
1125	            if (decimCount < decimationFactor)
1126	            {
1127	                // Upsample: output the last computed sample through anti-image
1128	                float upL = processBiquad(antiImageL, 0.0f);
1129	                float upR = processBiquad(antiImageR, 0.0f);
1130	                outL[i] = upL * static_cast<float>(decimationFactor);
1131	                outR[i] = upR * static_cast<float>(decimationFactor);
1132	                continue;
1133	            }
1134	            decimCount = 0;
1135	        }
1136	        else
1137	        {
1138	            monoIn = (inL[i] + inR[i]) * 0.5f;
1139	        }
1140	
1141	        // Feed into spectral engine input ring
1142	        buffers.inputRing[inputWritePos] = monoIn;
1143	        inputWritePos = (inputWritePos + 1) % fftSize;
1144	
1145	        samplesUntilNextHop--;
1146	        if (samplesUntilNextHop <= 0)
1147	        {
1148	            processHop(droneDensity, spectralDrift, freeze);
1149	            samplesUntilNextHop = hopSize;
1150	        }
1151	
1152	        // Read from overlap-add output
1153	        float outSamp = firstHopDone ? buffers.outputOverlap[outputReadPos] : 0.0f;
1154	        buffers.outputOverlap[outputReadPos] = 0.0f; // Clear for next overlap
1155	        outputReadPos = (outputReadPos + 1) % fftSize;
1156	
1157	        if (decimationFactor > 1)
1158	        {
1159	            // Feed through anti-image filter for upsampling
1160	            float upL = processBiquad(antiImageL, outSamp * static_cast<float>(decimationFactor));
1161	            float upR = processBiquad(antiImageR, outSamp * static_cast<float>(decimationFactor));
1162	            outL[i] = upL;
1163	            outR[i] = upR;
1164	        }
1165	        else
1166	        {
1167	            outL[i] = outSamp;
1168	            outR[i] = outSamp;
1169	        }
1170	    }
1171	}
1172	
