1255	        voices[v].delayL.prepare(static_cast<int>(maxDelaySamples));
1256	        voices[v].delayR.prepare(static_cast<int>(maxDelaySamples));
1257	        voices[v].baseDelaySamples = kBaseDelaysMs[v] * srFloat * 0.001f;
1258	        voices[v].modDepthSamples = kModDepthMs * srFloat * 0.001f;
1259	        voices[v].lfoInc = kLfoRates[v] / srFloat;
1260	        voices[v].lfoPhase = static_cast<float>(v) * 0.25f; // Spread initial phases
