1274	void ChorusEnsemble::process(juce::AudioBuffer<float>& buffer, float thickness)
1275	{
1276	    if (thickness < 0.001f) return; // Bypass
1277	
1278	    auto* left = buffer.getWritePointer(0);
1279	    auto* right = buffer.getWritePointer(1);
1280	    int numSamples = buffer.getNumSamples();
1281	
1282	    for (int i = 0; i < numSamples; ++i)
1283	    {
1284	        float dryL = left[i];
1285	        float dryR = right[i];
1286	        float wetL = 0.0f;
1287	        float wetR = 0.0f;
1288	
1289	        for (int v = 0; v < kNumVoices; ++v)
1290	        {
1291	            auto& voice = voices[v];
1292	
1293	            // Write input to delay
1294	            voice.delayL.write(dryL);
1295	            voice.delayR.write(dryR);
1296	
1297	            // LFO modulation
1298	            float lfoVal = std::sin(voice.lfoPhase * 2.0f * 3.14159265f);
1299	            voice.lfoPhase += voice.lfoInc;
1300	            if (voice.lfoPhase >= 1.0f) voice.lfoPhase -= 1.0f;
1301	
1302	            float delay = voice.baseDelaySamples + lfoVal * voice.modDepthSamples;
1303	            delay = std::max(delay, 1.0f);
1304	
1305	            wetL += voice.delayL.readInterp(delay);
1306	            wetR += voice.delayR.readInterp(delay);
1307	        }
1308	
1309	        // Average wet voices
1310	        wetL *= 0.25f;
1311	        wetR *= 0.25f;
1312	
1313	        // Crossfade dry/wet by thickness
1314	        left[i] = dryL * (1.0f - thickness) + wetL * thickness;
1315	        right[i] = dryR * (1.0f - thickness) + wetR * thickness;
1316	    }
1317	}
