1394	namespace CogDSP {
1395	
1396	float ResonantFilter::resonanceToQ(float reso01)
1397	{
1398	    // 0 -> Q=0.5, 1 -> Q=100 (exponential mapping)
1399	    return 0.5f * std::pow(200.0f, reso01);
1400	}
1401	
1402	void ResonantFilter::prepare(double sr)
1403	{
1404	    sampleRate = sr;
1405	    reset();
1406	}
