1408	void ResonantFilter::reset()
1409	{
1410	    ic1eq = 0.0f;
1411	    ic2eq = 0.0f;
1412	}
1413	
1414	float ResonantFilter::processSample(float input, float cutoffHz, float resonance01, FilterMode mode)
1415	{
1416	    float Q = resonanceToQ(resonance01);
1417	
1418	    // Bilinear transform: g = tan(pi * fc / sr)
1419	    float fc = std::clamp(cutoffHz, 20.0f, static_cast<float>(sampleRate * 0.49));
1420	    float g = std::tan(3.14159265f * fc / static_cast<float>(sampleRate));
1421	    float k = 1.0f / Q;
1422	
1423	    // TPT SVF (Cytomic / Andrew Simper)
1424	    float a1 = 1.0f / (1.0f + g * (g + k));
1425	    float a2 = g * a1;
1426	    float a3 = g * a2;
1427	
1428	    float v3 = input - ic2eq;
1429	    float v1 = a1 * ic1eq + a2 * v3;
1430	    float v2 = ic2eq + a2 * ic1eq + a3 * v3;
1431	
1432	    ic1eq = 2.0f * v1 - ic1eq;
1433	    ic2eq = 2.0f * v2 - ic2eq;
1434	
1435	    // Output modes
1436	    float lp = v2;
1437	    float bp = v1;
1438	    float hp = input - k * v1 - v2;
1439	
1440	    float output;
1441	    switch (mode)
1442	    {
1443	        case FilterMode::LP:    output = lp; break;
1444	        case FilterMode::HP:    output = hp; break;
1445	        case FilterMode::BP:    output = bp; break;
1446	        case FilterMode::Notch: output = lp + hp; break;
1447	        default:                output = lp; break;
1448	    }
1449	
1450	    // Auto-gain compensation: 1/sqrt(Q)
1451	    float compensation = 1.0f / std::sqrt(Q);
1452	    return output * compensation;
1453	}
