        void prepare(double sampleRate, float attackMs, float releaseMs);
        float process(float input);
    };

    EnvelopeFollower fastEnvL, fastEnvR;
    EnvelopeFollower slowEnvL, slowEnvR;

    // Coefficient smoothing (5ms one-pole)
    float smoothingCoeff = 0.0f;
    float smoothedCoeff = 0.0f;

    // Spectral flux (1024-point FFT for modulation)
    juce::dsp::FFT fft { 10 }; // 2^10 = 1024
    std::vector<float> fftInput;
    std::vector<float> fftOutput;
    std::vector<float> prevMagnitudes;
    int fftWritePos = 0;
    int fftSize = 1024;
    float spectralFlux = 0.0f;
    double currentSampleRate = 48000.0;

    void processSpectralFlux(float monoSample);
};

