#include "TextureBodyDetector.h"
#include <cmath>
#include <algorithm>

namespace CogDSP {

void TextureBodyDetector::EnvelopeFollower::prepare(double sampleRate, float attackMs, float releaseMs)
{
    attackCoeff = 1.0f - std::exp(-1.0f / (static_cast<float>(sampleRate) * attackMs * 0.001f));
    releaseCoeff = 1.0f - std::exp(-1.0f / (static_cast<float>(sampleRate) * releaseMs * 0.001f));
    envelope = 0.0f;
}

float TextureBodyDetector::EnvelopeFollower::process(float input)
{
    float absInput = std::fabs(input);
    float coeff = (absInput > envelope) ? attackCoeff : releaseCoeff;
    envelope += coeff * (absInput - envelope);
    return envelope;
}

void TextureBodyDetector::prepare(double sampleRate, int /*samplesPerBlock*/)
{
    currentSampleRate = sampleRate;

    // Fast: 2ms attack / 80ms release
    fastEnvL.prepare(sampleRate, 2.0f, 80.0f);
    fastEnvR.prepare(sampleRate, 2.0f, 80.0f);

    // Slow: 80ms attack / 400ms release
    slowEnvL.prepare(sampleRate, 80.0f, 400.0f);
    slowEnvR.prepare(sampleRate, 80.0f, 400.0f);

    // 5ms smoothing coefficient
    smoothingCoeff = 1.0f - std::exp(-1.0f / (static_cast<float>(sampleRate) * 0.005f));
    smoothedCoeff = 0.0f;

    // Spectral flux buffers
    fftInput.resize(fftSize * 2, 0.0f);
    fftOutput.resize(fftSize * 2, 0.0f);
    prevMagnitudes.resize(fftSize / 2, 0.0f);
    fftWritePos = 0;
    spectralFlux = 0.0f;
}

void TextureBodyDetector::reset()
{
    fastEnvL.envelope = 0.0f; fastEnvR.envelope = 0.0f;
    slowEnvL.envelope = 0.0f; slowEnvR.envelope = 0.0f;
    smoothedCoeff = 0.0f;
    std::fill(fftInput.begin(), fftInput.end(), 0.0f);
    std::fill(prevMagnitudes.begin(), prevMagnitudes.end(), 0.0f);
    fftWritePos = 0;
    spectralFlux = 0.0f;
}

float TextureBodyDetector::processSample(float inputL, float inputR, float sensitivity)
{
    float fastL = fastEnvL.process(inputL);
    float fastR = fastEnvR.process(inputR);
    float slowL = slowEnvL.process(inputL);
    float slowR = slowEnvR.process(inputR);

    // Average channels
    float fast = (fastL + fastR) * 0.5f;
    float slow = (slowL + slowR) * 0.5f;

    // Texture = fast - slow, scaled by sensitivity (1-8x)
    float sensGain = 1.0f + sensitivity * 7.0f;
    float rawCoeff = std::clamp((fast - slow) * sensGain, 0.0f, 1.0f);

    // Smooth to prevent AM artifacts
    smoothedCoeff += smoothingCoeff * (rawCoeff - smoothedCoeff);

    // Update spectral flux (non-routing modulation source)
    float mono = (inputL + inputR) * 0.5f;
    processSpectralFlux(mono);

    return smoothedCoeff;
}

void TextureBodyDetector::processSpectralFlux(float monoSample)
{
    fftInput[fftWritePos] = monoSample;
    fftWritePos++;

    if (fftWritePos >= fftSize)
    {
        fftWritePos = 0;

        // Copy to output buffer for in-place FFT
        std::copy(fftInput.begin(), fftInput.begin() + fftSize, fftOutput.begin());
        std::fill(fftOutput.begin() + fftSize, fftOutput.end(), 0.0f);

        fft.performRealOnlyForwardTransform(fftOutput.data());

        // Compute flux = sum of positive magnitude changes
        float flux = 0.0f;
        int numBins = fftSize / 2;
        for (int i = 0; i < numBins; ++i)
        {
            float re = fftOutput[i * 2];
            float im = fftOutput[i * 2 + 1];
            float mag = std::sqrt(re * re + im * im);
            float diff = mag - prevMagnitudes[i];
            if (diff > 0.0f) flux += diff;
            prevMagnitudes[i] = mag;
        }

        // Normalize by number of bins
        spectralFlux = flux / static_cast<float>(numBins);
    }
}

} // namespace CogDSP
