#include "Waveshaper.h"
#include <cmath>

namespace CogDSP {

void Waveshaper::prepare(double sampleRate, int spectralEngineLatencySamples)
{
    dcBlockerL.prepare(sampleRate);
    dcBlockerR.prepare(sampleRate);
    dcBlockerL.reset();
    dcBlockerR.reset();

    latencyCompSamples = spectralEngineLatencySamples;
    delayL.prepare(spectralEngineLatencySamples + 64);
    delayR.prepare(spectralEngineLatencySamples + 64);
    delayL.reset();
    delayR.reset();
}

void Waveshaper::reset()
{
    dcBlockerL.reset();
    dcBlockerR.reset();
    delayL.reset();
    delayR.reset();
}

float Waveshaper::processSample(float input, float drive)
{
    // Bypass at zero
    if (drive < 0.001f)
        return input;

    // Soft curve: tanh — warm, even harmonics
    float softGain = 1.0f + drive * 3.0f;
    float soft = fastTanh(input * softGain);

    // Hard curve: atan — asymmetric, odd+even harmonics, bounded
    float hardGain = 1.0f + drive * 8.0f;
    float hard = (2.0f / 3.14159265f) * fastAtan(input * hardGain);

    // Crossfade: low drive = soft, high drive = hard
    float t = std::clamp(drive * 2.0f - 1.0f, 0.0f, 1.0f); // 0-0.5 = soft, 0.5-1 = blend to hard
    float shaped;
    if (drive <= 0.5f)
        shaped = soft;
    else
        shaped = soft * (1.0f - t) + hard * t;

    // Blend with dry based on drive amount
    return input + drive * (shaped - input);
}

void Waveshaper::process(juce::AudioBuffer<float>& buffer, float textureDrive)
{
    auto* left = buffer.getWritePointer(0);
    auto* right = buffer.getWritePointer(1);
    int numSamples = buffer.getNumSamples();

    for (int i = 0; i < numSamples; ++i)
    {
        // Buffer already scaled by texture coefficient at split stage — no double-scaling
        float outL = processSample(left[i], textureDrive);
        float outR = processSample(right[i], textureDrive);

        // DC block
        outL = dcBlockerL.process(outL);
        outR = dcBlockerR.process(outR);

        // Write to latency compensation delay
        delayL.write(outL);
        delayR.write(outR);

        // Store compensated output back (for later merge read)
        left[i] = outL;
        right[i] = outR;
    }
}

} // namespace CogDSP
