#pragma once
#include <JuceHeader.h>
#include <complex>
#include <vector>

namespace CogDSP {

class SpectralDroneEngine
{
public:
    void prepare(double hostSampleRate, int samplesPerBlock);
    void reset();

    // Process stereo input, output mono (both channels same)
    // Returns number of output samples written (may differ from input due to resampling)
    void process(const juce::AudioBuffer<float>& input,
                 juce::AudioBuffer<float>& output,
                 float droneDensity,
                 float spectralDrift,
                 bool freeze);

    // Returns latency in HOST samples (accounts for decimation)
    int getHostLatencySamples() const { return fftSize * decimationFactor; }

private:
    static constexpr int kFFTOrder = 11;  // 2^11 = 2048
    static constexpr int fftSize = 2048;
    static constexpr int hopSize = 1024;  // 50% overlap
    static constexpr int numBins = fftSize / 2 + 1;

    juce::dsp::FFT fft { kFFTOrder };

    // Contiguous spectral buffers for cache locality
    struct SpectralBuffers {
        float inputRing[fftSize] = {};
        float outputOverlap[fftSize] = {};
        float window[fftSize] = {};
        float fftWorkspace[fftSize * 2] = {};
        float prevFrameRe[numBins] = {};
        float prevFrameIm[numBins] = {};
        float driftTempRe[numBins] = {};  // pre-allocated for spectral drift (avoids ~8KB stack alloc)
        float driftTempIm[numBins] = {};
    };
    SpectralBuffers buffers;

    int inputWritePos = 0;
    int outputReadPos = 0;
    int samplesUntilNextHop = 0;
    bool firstHopDone = false;

    // Freeze crossfade
    float freezeGain = 0.0f;     // 0 = live, 1 = frozen
    float freezeTarget = 0.0f;
    float freezeSmoothCoeff = 0.0f;

    // Downsampling
    double hostRate = 48000.0;
    int decimationFactor = 1;
    int decimCount = 0;  // persistent across processBlock calls

    // Butterworth LP for anti-alias/anti-image (2nd order)
    struct BiquadState {
        float x1 = 0, x2 = 0, y1 = 0, y2 = 0;
        float b0 = 1, b1 = 0, b2 = 0, a1 = 0, a2 = 0;
    };
    BiquadState antiAliasL, antiAliasR;
    BiquadState antiImageL, antiImageR;

    void computeButterworthLP(BiquadState& state, double sampleRate, double cutoff);
    float processBiquad(BiquadState& state, float input);

    void processHop(float droneDensity, float spectralDrift, bool freeze);
    void precomputeWindow();
};

} // namespace CogDSP
