#include "SpectralDroneEngine.h"
#include <cmath>
#include <algorithm>

namespace CogDSP {

void SpectralDroneEngine::prepare(double hostSampleRate, int /*samplesPerBlock*/)
{
    hostRate = hostSampleRate;

    // Compute decimation factor (target ~48kHz internal)
    if (hostSampleRate > 96000.0)
        decimationFactor = static_cast<int>(std::round(hostSampleRate / 48000.0));
    else if (hostSampleRate > 48000.0)
        decimationFactor = 2;
    else
        decimationFactor = 1;

    // Anti-alias filter at 20kHz (before decimation)
    if (decimationFactor > 1)
    {
        computeButterworthLP(antiAliasL, hostSampleRate, 20000.0);
        computeButterworthLP(antiAliasR, hostSampleRate, 20000.0);
        computeButterworthLP(antiImageL, hostSampleRate, 20000.0);
        computeButterworthLP(antiImageR, hostSampleRate, 20000.0);
    }

    // Freeze smoothing: ~50ms at internal rate
    double internalRate = hostSampleRate / decimationFactor;
    freezeSmoothCoeff = 1.0f - std::exp(-1.0f / (static_cast<float>(internalRate) * 0.05f));

    precomputeWindow();
    reset();
}

void SpectralDroneEngine::reset()
{
    std::memset(&buffers, 0, sizeof(buffers));
    precomputeWindow(); // Re-fill window after memset
    inputWritePos = 0;
    outputReadPos = 0;
    samplesUntilNextHop = fftSize; // Need full window before first hop
    firstHopDone = false;
    freezeGain = 0.0f;
    freezeTarget = 0.0f;
    decimCount = 0;
    antiAliasL = antiAliasR = BiquadState{};
    antiImageL = antiImageR = BiquadState{};
    if (decimationFactor > 1)
    {
        computeButterworthLP(antiAliasL, hostRate, 20000.0);
        computeButterworthLP(antiAliasR, hostRate, 20000.0);
        computeButterworthLP(antiImageL, hostRate, 20000.0);
        computeButterworthLP(antiImageR, hostRate, 20000.0);
    }
}

void SpectralDroneEngine::precomputeWindow()
{
    for (int i = 0; i < fftSize; ++i)
        buffers.window[i] = 0.5f * (1.0f - std::cos(2.0f * 3.14159265f * i / fftSize));
}

void SpectralDroneEngine::computeButterworthLP(BiquadState& state, double sampleRate, double cutoff)
{
    double w0 = 2.0 * 3.14159265358979 * cutoff / sampleRate;
    double cosw0 = std::cos(w0);
    double sinw0 = std::sin(w0);
    double alpha = sinw0 / (2.0 * 0.7071067811865476); // Q = sqrt(2)/2 for Butterworth

    double a0 = 1.0 + alpha;
    state.b0 = static_cast<float>((1.0 - cosw0) / 2.0 / a0);
    state.b1 = static_cast<float>((1.0 - cosw0) / a0);
    state.b2 = state.b0;
    state.a1 = static_cast<float>(-2.0 * cosw0 / a0);
    state.a2 = static_cast<float>((1.0 - alpha) / a0);
    state.x1 = state.x2 = state.y1 = state.y2 = 0.0f;
}

float SpectralDroneEngine::processBiquad(BiquadState& s, float input)
{
    float output = s.b0 * input + s.b1 * s.x1 + s.b2 * s.x2 - s.a1 * s.y1 - s.a2 * s.y2;
    s.x2 = s.x1; s.x1 = input;
    s.y2 = s.y1; s.y1 = output;
    return output;
}

void SpectralDroneEngine::processHop(float droneDensity, float spectralDrift, bool freeze)
{
    // Smooth freeze transition
    freezeTarget = freeze ? 1.0f : 0.0f;
    freezeGain += freezeSmoothCoeff * (freezeTarget - freezeGain);

    // Effective blend coefficient
    float blendCoeff = std::max(droneDensity, freezeGain);

    // Window the input and copy to workspace
    for (int i = 0; i < fftSize; ++i)
    {
        int readIdx = (inputWritePos - fftSize + i + fftSize * 2) % (fftSize);
        buffers.fftWorkspace[i] = buffers.inputRing[readIdx] * buffers.window[i];
    }
    std::fill(buffers.fftWorkspace + fftSize, buffers.fftWorkspace + fftSize * 2, 0.0f);

    // Forward FFT
    fft.performRealOnlyForwardTransform(buffers.fftWorkspace);

    // Spectral processing: blend with previous frame (branch-free)
    float oneMinusBlend = 1.0f - blendCoeff;
    for (int bin = 0; bin < numBins; ++bin)
    {
        float re = buffers.fftWorkspace[bin * 2];
        float im = buffers.fftWorkspace[bin * 2 + 1];

        re = re * oneMinusBlend + buffers.prevFrameRe[bin] * blendCoeff;
        im = im * oneMinusBlend + buffers.prevFrameIm[bin] * blendCoeff;

        buffers.prevFrameRe[bin] = re;
        buffers.prevFrameIm[bin] = im;

        buffers.fftWorkspace[bin * 2] = re;
        buffers.fftWorkspace[bin * 2 + 1] = im;
    }

    // Spectral drift: rotate bins (skip if frozen or drift near zero)
    if (std::fabs(spectralDrift) > 0.001f && freezeGain < 0.99f)
    {
        float shiftBins = spectralDrift * 10.0f; // ±10 bins at full drift
        int shiftInt = static_cast<int>(shiftBins);
        float shiftFrac = shiftBins - static_cast<float>(shiftInt);

        // Use pre-allocated member buffers (avoids ~8KB stack alloc in audio thread)
        std::memset(buffers.driftTempRe, 0, sizeof(float) * numBins);
        std::memset(buffers.driftTempIm, 0, sizeof(float) * numBins);

        for (int bin = 0; bin < numBins; ++bin)
        {
            int srcBin = bin - shiftInt;
            int srcBin2 = srcBin - 1;

            if (srcBin >= 0 && srcBin < numBins && srcBin2 >= 0 && srcBin2 < numBins)
            {
                float frac = (shiftBins >= 0.0f) ? shiftFrac : -shiftFrac;
                buffers.driftTempRe[bin] = buffers.fftWorkspace[srcBin * 2] * (1.0f - frac)
                                         + buffers.fftWorkspace[srcBin2 * 2] * frac;
                buffers.driftTempIm[bin] = buffers.fftWorkspace[srcBin * 2 + 1] * (1.0f - frac)
                                         + buffers.fftWorkspace[srcBin2 * 2 + 1] * frac;
            }
        }

        for (int bin = 0; bin < numBins; ++bin)
        {
            buffers.fftWorkspace[bin * 2] = buffers.driftTempRe[bin];
            buffers.fftWorkspace[bin * 2 + 1] = buffers.driftTempIm[bin];
        }
    }

    // Inverse FFT
    fft.performRealOnlyInverseTransform(buffers.fftWorkspace);

    // Overlap-add to output buffer
    for (int i = 0; i < fftSize; ++i)
    {
        int outIdx = (outputReadPos + i) % fftSize;
        if (firstHopDone)
            buffers.outputOverlap[outIdx] += buffers.fftWorkspace[i] * buffers.window[i];
        else
            buffers.outputOverlap[outIdx] = buffers.fftWorkspace[i] * buffers.window[i];
    }

    firstHopDone = true;
}

void SpectralDroneEngine::process(const juce::AudioBuffer<float>& input,
                                   juce::AudioBuffer<float>& output,
                                   float droneDensity,
                                   float spectralDrift,
                                   bool freeze)
{
    auto* inL = input.getReadPointer(0);
    auto* inR = input.getReadPointer(1);
    auto* outL = output.getWritePointer(0);
    auto* outR = output.getWritePointer(1);
    int numSamples = input.getNumSamples();

    // decimCount is a member variable — persists across processBlock calls
    int outSample = 0;

    for (int i = 0; i < numSamples; ++i)
    {
        float monoIn;
        if (decimationFactor > 1)
        {
            // Anti-alias filter
            float filtL = processBiquad(antiAliasL, inL[i]);
            float filtR = processBiquad(antiAliasR, inR[i]);
            monoIn = (filtL + filtR) * 0.5f;

            // Decimation: only process every N-th sample
            decimCount++;
            if (decimCount < decimationFactor)
            {
                // Upsample: output the last computed sample through anti-image
                float upL = processBiquad(antiImageL, 0.0f);
                float upR = processBiquad(antiImageR, 0.0f);
                outL[i] = upL * static_cast<float>(decimationFactor);
                outR[i] = upR * static_cast<float>(decimationFactor);
                continue;
            }
            decimCount = 0;
        }
        else
        {
            monoIn = (inL[i] + inR[i]) * 0.5f;
        }

        // Feed into spectral engine input ring
        buffers.inputRing[inputWritePos] = monoIn;
        inputWritePos = (inputWritePos + 1) % fftSize;

        samplesUntilNextHop--;
        if (samplesUntilNextHop <= 0)
        {
            processHop(droneDensity, spectralDrift, freeze);
            samplesUntilNextHop = hopSize;
        }

        // Read from overlap-add output
        float outSamp = firstHopDone ? buffers.outputOverlap[outputReadPos] : 0.0f;
        buffers.outputOverlap[outputReadPos] = 0.0f; // Clear for next overlap
        outputReadPos = (outputReadPos + 1) % fftSize;

        if (decimationFactor > 1)
        {
            // Feed through anti-image filter for upsampling
            float upL = processBiquad(antiImageL, outSamp * static_cast<float>(decimationFactor));
            float upR = processBiquad(antiImageR, outSamp * static_cast<float>(decimationFactor));
            outL[i] = upL;
            outR[i] = upR;
        }
        else
        {
            outL[i] = outSamp;
            outR[i] = outSamp;
        }
    }
}

} // namespace CogDSP
