#pragma once
#include <JuceHeader.h>
#include <array>
#include "DelayLine.h"

namespace CogDSP {

class ChorusEnsemble
{
public:
    void prepare(double sampleRate, int samplesPerBlock);
    void reset();

    // Process stereo buffer in-place
    void process(juce::AudioBuffer<float>& buffer, float thickness);

private:
    static constexpr int kNumVoices = 4;

    // Base delays in ms: 3, 7, 11, 16 (prime-ish spacing)
    static constexpr std::array<float, kNumVoices> kBaseDelaysMs = { 3.0f, 7.0f, 11.0f, 16.0f };

    // LFO rates per voice: 0.8, 1.1, 1.5, 2.1 Hz
    static constexpr std::array<float, kNumVoices> kLfoRates = { 0.8f, 1.1f, 1.5f, 2.1f };

    // Modulation depth: ±0.5ms
    static constexpr float kModDepthMs = 0.5f;

    struct Voice {
        DelayLine delayL, delayR;
        float lfoPhase = 0.0f;
        float lfoInc = 0.0f;
        float baseDelaySamples = 0.0f;
        float modDepthSamples = 0.0f;
    };

    Voice voices[kNumVoices];
    double currentSampleRate = 48000.0;
    int blockUpdateInterval = 32;
};

