#include "ChorusEnsemble.h"
#include <cmath>

namespace CogDSP {

void ChorusEnsemble::prepare(double sampleRate, int /*samplesPerBlock*/)
{
    currentSampleRate = sampleRate;
    float srFloat = static_cast<float>(sampleRate);

    for (int v = 0; v < kNumVoices; ++v)
    {
        float maxDelaySamples = (kBaseDelaysMs[v] + kModDepthMs) * srFloat * 0.001f + 4.0f;
        voices[v].delayL.prepare(static_cast<int>(maxDelaySamples));
        voices[v].delayR.prepare(static_cast<int>(maxDelaySamples));
        voices[v].baseDelaySamples = kBaseDelaysMs[v] * srFloat * 0.001f;
        voices[v].modDepthSamples = kModDepthMs * srFloat * 0.001f;
        voices[v].lfoInc = kLfoRates[v] / srFloat;
        voices[v].lfoPhase = static_cast<float>(v) * 0.25f; // Spread initial phases
    }
}

void ChorusEnsemble::reset()
{
    for (int v = 0; v < kNumVoices; ++v)
    {
        voices[v].delayL.reset();
        voices[v].delayR.reset();
        voices[v].lfoPhase = static_cast<float>(v) * 0.25f;
    }
}

void ChorusEnsemble::process(juce::AudioBuffer<float>& buffer, float thickness)
{
    if (thickness < 0.001f) return; // Bypass

    auto* left = buffer.getWritePointer(0);
    auto* right = buffer.getWritePointer(1);
    int numSamples = buffer.getNumSamples();

    for (int i = 0; i < numSamples; ++i)
    {
        float dryL = left[i];
        float dryR = right[i];
        float wetL = 0.0f;
        float wetR = 0.0f;

        for (int v = 0; v < kNumVoices; ++v)
        {
            auto& voice = voices[v];

            // Write input to delay
            voice.delayL.write(dryL);
            voice.delayR.write(dryR);

            // LFO modulation
            float lfoVal = std::sin(voice.lfoPhase * 2.0f * 3.14159265f);
            voice.lfoPhase += voice.lfoInc;
            if (voice.lfoPhase >= 1.0f) voice.lfoPhase -= 1.0f;

            float delay = voice.baseDelaySamples + lfoVal * voice.modDepthSamples;
            delay = std::max(delay, 1.0f);

            wetL += voice.delayL.readInterp(delay);
            wetR += voice.delayR.readInterp(delay);
        }

        // Average wet voices
        wetL *= 0.25f;
        wetR *= 0.25f;

        // Crossfade dry/wet by thickness
        left[i] = dryL * (1.0f - thickness) + wetL * thickness;
        right[i] = dryR * (1.0f - thickness) + wetR * thickness;
    }
}

} // namespace CogDSP
