#pragma once
#include <JuceHeader.h>

namespace CogDSP {

enum class FilterMode { LP, HP, BP, Notch };

class ResonantFilter
{
public:
    void prepare(double sampleRate);
    void reset();

    // Process single sample, returns filtered output with auto-gain applied
    float processSample(float input, float cutoffHz, float resonance01, FilterMode mode);

    // Map 0-1 resonance to Q 0.5–100
    static float resonanceToQ(float reso01);

private:
    double sampleRate = 48000.0;
    float ic1eq = 0.0f; // integrator state 1
    float ic2eq = 0.0f; // integrator state 2
};

// Dual filter: two bands, parallel or series
class DualResonantFilter
{
public:
    void prepare(double sampleRate);
    void reset();

    // Process stereo buffer in-place
    void process(juce::AudioBuffer<float>& buffer,
                 float cutoffA, float resoA, FilterMode modeA,
                 float cutoffB, float resoB, FilterMode modeB,
                 bool seriesMode);

private:
    ResonantFilter filterAL, filterAR;
    ResonantFilter filterBL, filterBR;
};

} // namespace CogDSP
