#include "ResonantFilter.h"
#include <cmath>
#include <algorithm>

namespace CogDSP {

float ResonantFilter::resonanceToQ(float reso01)
{
    // 0 -> Q=0.5, 1 -> Q=100 (exponential mapping)
    return 0.5f * std::pow(200.0f, reso01);
}

void ResonantFilter::prepare(double sr)
{
    sampleRate = sr;
    reset();
}

void ResonantFilter::reset()
{
    ic1eq = 0.0f;
    ic2eq = 0.0f;
}

float ResonantFilter::processSample(float input, float cutoffHz, float resonance01, FilterMode mode)
{
    float Q = resonanceToQ(resonance01);

    // Bilinear transform: g = tan(pi * fc / sr)
    float fc = std::clamp(cutoffHz, 20.0f, static_cast<float>(sampleRate * 0.49));
    float g = std::tan(3.14159265f * fc / static_cast<float>(sampleRate));
    float k = 1.0f / Q;

    // TPT SVF (Cytomic / Andrew Simper)
    float a1 = 1.0f / (1.0f + g * (g + k));
    float a2 = g * a1;
    float a3 = g * a2;

    float v3 = input - ic2eq;
    float v1 = a1 * ic1eq + a2 * v3;
    float v2 = ic2eq + a2 * ic1eq + a3 * v3;

    ic1eq = 2.0f * v1 - ic1eq;
    ic2eq = 2.0f * v2 - ic2eq;

    // Output modes
    float lp = v2;
    float bp = v1;
    float hp = input - k * v1 - v2;

    float output;
    switch (mode)
    {
        case FilterMode::LP:    output = lp; break;
        case FilterMode::HP:    output = hp; break;
        case FilterMode::BP:    output = bp; break;
        case FilterMode::Notch: output = lp + hp; break;
        default:                output = lp; break;
    }

    // Auto-gain compensation: 1/sqrt(Q)
    float compensation = 1.0f / std::sqrt(Q);
    return output * compensation;
}

void DualResonantFilter::prepare(double sampleRate)
{
    filterAL.prepare(sampleRate);
    filterAR.prepare(sampleRate);
    filterBL.prepare(sampleRate);
    filterBR.prepare(sampleRate);
}

void DualResonantFilter::reset()
{
    filterAL.reset(); filterAR.reset();
    filterBL.reset(); filterBR.reset();
}

void DualResonantFilter::process(juce::AudioBuffer<float>& buffer,
                                  float cutoffA, float resoA, FilterMode modeA,
                                  float cutoffB, float resoB, FilterMode modeB,
                                  bool seriesMode)
{
    auto* left = buffer.getWritePointer(0);
    auto* right = buffer.getWritePointer(1);
    int numSamples = buffer.getNumSamples();

    for (int i = 0; i < numSamples; ++i)
    {
        if (seriesMode)
        {
            // Series: A -> B
            float aL = filterAL.processSample(left[i], cutoffA, resoA, modeA);
            float aR = filterAR.processSample(right[i], cutoffA, resoA, modeA);
            left[i] = filterBL.processSample(aL, cutoffB, resoB, modeB);
            right[i] = filterBR.processSample(aR, cutoffB, resoB, modeB);
        }
        else
        {
            // Parallel: A + B
            float aL = filterAL.processSample(left[i], cutoffA, resoA, modeA);
            float aR = filterAR.processSample(right[i], cutoffA, resoA, modeA);
            float bL = filterBL.processSample(left[i], cutoffB, resoB, modeB);
            float bR = filterBR.processSample(right[i], cutoffB, resoB, modeB);
            left[i] = (aL + bL) * 0.5f;
            right[i] = (aR + bR) * 0.5f;
        }
    }
}

