1608	    // === Pre-compute tone tilt coefficients ONCE (not per-sample) ===
1609	    float toneAmount = (tone - 0.5f) * 2.0f; // -1 to +1
1610	    float cutoff = 1000.0f;
1611	    float rc = 1.0f / (2.0f * 3.14159265f * cutoff);
1612	    float dt = 1.0f / static_cast<float>(currentSampleRate);
1613	    float alpha = dt / (rc + dt);
1614	    float gainHigh = std::pow(10.0f, toneAmount * 6.0f / 20.0f); // ±6dB
1615	
1616	    for (int i = 0; i < numSamples; ++i)
