1627	            float pgDB = drive * 24.0f;
1628	            if (rms > 1.0f)
1629	                pgDB -= 20.0f * std::log10(rms) * 0.9f; // ~10:1 compression
1630	            pgDB = std::max(pgDB, -6.0f);
1631	            return std::pow(10.0f, pgDB / 20.0f);
1632	        };
1633	
1634	        float preGainL = computePreGain(rmsL);
1635	        float preGainR = computePreGain(rmsR);
