1738	    lpCoeffs.b1 = static_cast<float>((1.0 - cosw0) / a0);
1739	    lpCoeffs.b2 = lpCoeffs.b0;
1740	    lpCoeffs.a1 = static_cast<float>(-2.0 * cosw0 / a0);
1741	    lpCoeffs.a2 = static_cast<float>((1.0 - alpha) / a0);
