1919	#include "ModulationEngine.h"
1920	#include <algorithm>
1921	
1922	namespace CogDSP {
1923	
1924	void ModulationEngine::prepare(double sampleRate, int samplesPerBlock)
1925	{
1926	    currentSampleRate = sampleRate;
1927	    currentBlockSize = std::max(samplesPerBlock, 32);
1928	
1929	    // Base rates (irrational ratios)
1930	    lfoA.baseRate = 0.07f;
1931	    lfoB.baseRate = 0.13f;
1932	    lfoC.baseRate = 0.23f;
1933	
1934	    // Audio-reactive smoothing: 10ms attack / 100ms release (spec §5.1)
1935	    audioEnvAttackCoeff = 1.0f - std::exp(-1.0f / (static_cast<float>(sampleRate) * 0.01f));
1936	    audioEnvReleaseCoeff = 1.0f - std::exp(-1.0f / (static_cast<float>(sampleRate) * 0.1f));
1937	
1938	    reset();
1939	}
1940	
1941	void ModulationEngine::reset()
1942	{
1943	    lfoA.phase = 0.0f; lfoA.output = 0.0f;
1944	    lfoB.phase = 0.33f; lfoB.output = 0.0f; // Offset phases
1945	    lfoC.phase = 0.66f; lfoC.output = 0.0f;
1946	    audioEnvSmoothed = 0.0f;
1947	    filterAMod = filterBMod = spectralDriftMod = chorusDepthMod = 0.0f;
1948	}
1949	
1950	void ModulationEngine::updateBlock(float evolutionSpeed, float complexity, float reactivity,
1951	                                    float audioEnvelope, float spectralFlux)
1952	{
1953	    // Speed multiplier: 0.1x to 10x
1954	    float speedMult = 0.1f * std::pow(100.0f, evolutionSpeed);
1955	
1956	    // Cross-modulation: each LFO modulates the next's rate
1957	    // A -> B -> C -> A ring
1958	    float modDepth = complexity * 2.0f;
1959	
1960	    // Compute modulated rates with bounds
1961	    auto boundRate = [](float baseRate, float modOutput, float modDepth, float speedMult) -> float
1962	    {
1963	        float rate = baseRate * speedMult * std::pow(2.0f, modOutput * modDepth);
1964	        float minRate = std::max(baseRate * speedMult * 0.25f, 0.01f);
1965	        float maxRate = std::min(baseRate * speedMult * 4.0f, 20.0f);
1966	        return std::clamp(rate, minRate, maxRate);
1967	    };
1968	
1969	    float rateA = boundRate(lfoA.baseRate, lfoC.output, modDepth, speedMult);
1970	    float rateB = boundRate(lfoB.baseRate, lfoA.output, modDepth, speedMult);
1971	    float rateC = boundRate(lfoC.baseRate, lfoB.output, modDepth, speedMult);
1972	
1973	    // Advance LFOs
1974	    lfoA.advance(rateA, static_cast<float>(currentSampleRate), currentBlockSize);
1975	    lfoB.advance(rateB, static_cast<float>(currentSampleRate), currentBlockSize);
1976	    lfoC.advance(rateC, static_cast<float>(currentSampleRate), currentBlockSize);
1977	
1978	    // Smooth audio envelope with asymmetric attack/release
1979	    float envCoeff = (audioEnvelope > audioEnvSmoothed) ? audioEnvAttackCoeff : audioEnvReleaseCoeff;
1980	    audioEnvSmoothed += envCoeff * (audioEnvelope - audioEnvSmoothed);
1981	
1982	    // Compute modulation outputs (in octaves, each clamped ±2)
1983	    float lfoAOct = std::clamp(lfoA.output * 2.0f, -2.0f, 2.0f);
1984	    float lfoBOct = std::clamp(lfoB.output * 2.0f, -2.0f, 2.0f);
1985	    float lfoCOct = std::clamp(lfoC.output * 2.0f, -2.0f, 2.0f);
1986	    float audioOct = std::clamp(audioEnvSmoothed * reactivity * 2.0f, -2.0f, 2.0f);
1987	    float fluxOct = std::clamp(spectralFlux * reactivity * 2.0f, -2.0f, 2.0f);
1988	
1989	    // Filter A: LFO A + audio + flux, total clamped ±4
1990	    filterAMod = std::clamp(lfoAOct + audioOct + fluxOct, -4.0f, 4.0f);
1991	
1992	    // Filter B: LFO B + audio + flux, total clamped ±4
1993	    filterBMod = std::clamp(lfoBOct + audioOct + fluxOct, -4.0f, 4.0f);
1994	
1995	    // Spectral drift: LFO C, subtle (±0.5 of drift range)
1996	    spectralDriftMod = lfoC.output * 0.5f;
1997	
1998	    // Chorus depth: LFO A secondary, ±20% of thickness
1999	    chorusDepthMod = lfoA.output * 0.2f;
2000	}
2001	
2002	} // namespace CogDSP
