#include "DriveCircuit.h"
#include <cmath>
#include <algorithm>

namespace CogDSP {

void DriveCircuit::prepare(double sampleRate)
{
    currentSampleRate = sampleRate;
    // ~5ms RMS window
    rmsCoeff = 1.0f - std::exp(-1.0f / (static_cast<float>(sampleRate) * 0.005f));
    reset();
}

void DriveCircuit::reset()
{
    rmsEnvelopeL = 0.0f;
    rmsEnvelopeR = 0.0f;
    tiltL = tiltR = TiltState{};
}

float DriveCircuit::processSample(float input, float drive)
{
    // Bypass at zero
    if (drive < 0.001f)
        return input;

    // Stage 2: Saturation core (pre-gain applied externally per-channel)
    float warm = fastTanh(input * (1.0f + drive * 3.0f));
    float grit = input / (1.0f + std::fabs(input)) + 0.1f * std::sin(input * 3.14159265f) * fastGaussian(input);

    // Blend: drive 0-0.5 = warm, 0.5-1 = blend to grit
    float blendT = std::clamp(drive * 2.0f - 1.0f, 0.0f, 1.0f);
    float saturated = warm * (1.0f - blendT) + grit * blendT;

    return saturated;
}

void DriveCircuit::process(juce::AudioBuffer<float>& buffer, float drive, float tone)
{
    if (drive < 0.001f) return; // Full bypass

    auto* left = buffer.getWritePointer(0);
    auto* right = buffer.getWritePointer(1);
    int numSamples = buffer.getNumSamples();

    // === Pre-compute tone tilt coefficients ONCE (not per-sample) ===
    float toneAmount = (tone - 0.5f) * 2.0f; // -1 to +1
    float cutoff = 1000.0f;
    float rc = 1.0f / (2.0f * 3.14159265f * cutoff);
    float dt = 1.0f / static_cast<float>(currentSampleRate);
    float alpha = dt / (rc + dt);
    float gainHigh = std::pow(10.0f, toneAmount * 6.0f / 20.0f); // ±6dB

    for (int i = 0; i < numSamples; ++i)
    {
        // Stage 1: Per-channel adaptive pre-gain (RMS tracked independently)
        float absL = std::fabs(left[i]);
        float absR = std::fabs(right[i]);
        rmsEnvelopeL += rmsCoeff * (absL * absL - rmsEnvelopeL);
        rmsEnvelopeR += rmsCoeff * (absR * absR - rmsEnvelopeR);
        float rmsL = std::sqrt(rmsEnvelopeL + 1e-12f);
        float rmsR = std::sqrt(rmsEnvelopeR + 1e-12f);

        auto computePreGain = [&](float rms) -> float {
            float pgDB = drive * 24.0f;
            if (rms > 1.0f)
                pgDB -= 20.0f * std::log10(rms) * 0.9f; // ~10:1 compression
            pgDB = std::max(pgDB, -6.0f);
            return std::pow(10.0f, pgDB / 20.0f);
        };

        float preGainL = computePreGain(rmsL);
        float preGainR = computePreGain(rmsR);

        // Stage 2: Saturate (with per-channel pre-gain applied)
        left[i] = processSample(left[i] * preGainL, drive);
        right[i] = processSample(right[i] * preGainR, drive);

        // Stage 3: Tone tilt (coefficients pre-computed above)
        float lpL = tiltL.prevOut + alpha * (left[i] - tiltL.prevOut);
        float lpR = tiltR.prevOut + alpha * (right[i] - tiltR.prevOut);
        tiltL.prevOut = lpL;
        tiltR.prevOut = lpR;

        float hpL = left[i] - lpL;
        float hpR = right[i] - lpR;

        left[i] = lpL + hpL * gainHigh;
        right[i] = lpR + hpR * gainHigh;
    }
}

} // namespace CogDSP
