#pragma once
#include <JuceHeader.h>

namespace CogDSP {

class StereoWidener
{
public:
    void prepare(double sampleRate);
    void reset();

    // Process stereo buffer in-place
    void process(juce::AudioBuffer<float>& buffer, float width);

private:
    // Linkwitz-Riley 2nd-order crossover at 250Hz
    // Implemented as two cascaded Butterworth (same coefficients)
    struct LR2State {
        // First biquad stage
        float x1a = 0, x2a = 0, y1a = 0, y2a = 0;
        // Second biquad stage
        float x1b = 0, x2b = 0, y1b = 0, y2b = 0;
    };

    struct LR2Coeffs {
        float b0 = 0, b1 = 0, b2 = 0, a1 = 0, a2 = 0;
    };

    LR2Coeffs lpCoeffs, hpCoeffs;
    LR2State lpStateL, lpStateR;
    LR2State hpStateL, hpStateR;

    float processLR2LP(LR2State& state, float input);
    float processLR2HP(LR2State& state, float input);
};

} // namespace CogDSP
