#include "StereoWidener.h"
#include <cmath>

namespace CogDSP {

void StereoWidener::prepare(double sampleRate)
{
    // Linkwitz-Riley = 2x cascaded Butterworth
    double fc = 250.0;
    double w0 = 2.0 * 3.14159265358979 * fc / sampleRate;
    double cosw0 = std::cos(w0);
    double sinw0 = std::sin(w0);
    double alpha = sinw0 / (2.0 * 0.7071067811865476); // Q = sqrt(2)/2

    double a0;

    // LP coefficients
    a0 = 1.0 + alpha;
    lpCoeffs.b0 = static_cast<float>((1.0 - cosw0) / 2.0 / a0);
    lpCoeffs.b1 = static_cast<float>((1.0 - cosw0) / a0);
    lpCoeffs.b2 = lpCoeffs.b0;
    lpCoeffs.a1 = static_cast<float>(-2.0 * cosw0 / a0);
    lpCoeffs.a2 = static_cast<float>((1.0 - alpha) / a0);

    // HP coefficients
    a0 = 1.0 + alpha;
    hpCoeffs.b0 = static_cast<float>((1.0 + cosw0) / 2.0 / a0);
    hpCoeffs.b1 = static_cast<float>(-(1.0 + cosw0) / a0);
    hpCoeffs.b2 = hpCoeffs.b0;
    hpCoeffs.a1 = lpCoeffs.a1; // Same denominator
    hpCoeffs.a2 = lpCoeffs.a2;

    reset();
}

void StereoWidener::reset()
{
    lpStateL = lpStateR = LR2State{};
    hpStateL = hpStateR = LR2State{};
}

float StereoWidener::processLR2LP(LR2State& s, float input)
{
    // First Butterworth LP stage
    float y1 = lpCoeffs.b0 * input + lpCoeffs.b1 * s.x1a + lpCoeffs.b2 * s.x2a
             - lpCoeffs.a1 * s.y1a - lpCoeffs.a2 * s.y2a;
    s.x2a = s.x1a; s.x1a = input;
    s.y2a = s.y1a; s.y1a = y1;

    // Second Butterworth LP stage (cascaded = LR2)
    float y2 = lpCoeffs.b0 * y1 + lpCoeffs.b1 * s.x1b + lpCoeffs.b2 * s.x2b
             - lpCoeffs.a1 * s.y1b - lpCoeffs.a2 * s.y2b;
    s.x2b = s.x1b; s.x1b = y1;
    s.y2b = s.y1b; s.y1b = y2;

    return y2;
}

float StereoWidener::processLR2HP(LR2State& s, float input)
{
    float y1 = hpCoeffs.b0 * input + hpCoeffs.b1 * s.x1a + hpCoeffs.b2 * s.x2a
             - hpCoeffs.a1 * s.y1a - hpCoeffs.a2 * s.y2a;
    s.x2a = s.x1a; s.x1a = input;
    s.y2a = s.y1a; s.y1a = y1;

    float y2 = hpCoeffs.b0 * y1 + hpCoeffs.b1 * s.x1b + hpCoeffs.b2 * s.x2b
             - hpCoeffs.a1 * s.y1b - hpCoeffs.a2 * s.y2b;
    s.x2b = s.x1b; s.x1b = y1;
    s.y2b = s.y1b; s.y1b = y2;

    return y2;
}

void StereoWidener::process(juce::AudioBuffer<float>& buffer, float width)
{
    auto* left = buffer.getWritePointer(0);
    auto* right = buffer.getWritePointer(1);
    int numSamples = buffer.getNumSamples();

    // Always process through crossover filters to keep state fresh (prevents click on enable)
    float sideGain = 1.0f + width * 2.0f;

    for (int i = 0; i < numSamples; ++i)
    {
        float L = left[i];
        float R = right[i];

        // Split into low and high (always processed to maintain filter state)
        float lowL = processLR2LP(lpStateL, L);
        float lowR = processLR2LP(lpStateR, R);
        float highL = processLR2HP(hpStateL, L);
        float highR = processLR2HP(hpStateR, R);

        if (width < 0.001f)
        {
            // Transparent: recombine without M/S processing
            left[i] = lowL + highL;
            right[i] = lowR + highR;
        }
        else
        {
            // Low: mono sum
            float lowMono = (lowL + lowR) * 0.5f;

            // High: M/S widening
            float mid = (highL + highR) * 0.5f;
            float side = (highL - highR) * 0.5f;
            side *= sideGain;

            float widenedL = mid + side;
            float widenedR = mid - side;

            // Recombine
            left[i] = lowMono + widenedL;
            right[i] = lowMono + widenedR;
        }
    }
}

} // namespace CogDSP
