#pragma once
#include <cmath>

namespace CogDSP {

class ModulationEngine
{
public:
    void prepare(double sampleRate, int samplesPerBlock);
    void reset();

    // Call once per block with current parameter values and audio-reactive input
    void updateBlock(float evolutionSpeed, float complexity, float reactivity,
                     float audioEnvelope, float spectralFlux);

    // Get modulation outputs (in octaves, ±2 max per source, ±4 total)
    float getFilterAModOctaves() const { return filterAMod; }
    float getFilterBModOctaves() const { return filterBMod; }
    float getSpectralDriftMod() const { return spectralDriftMod; }
    float getChorusDepthMod() const { return chorusDepthMod; }

private:
    struct LFO {
        float phase = 0.0f;
        float baseRate = 0.0f;
        float currentRate = 0.0f;
        float output = 0.0f;

        void advance(float rateHz, float sampleRate, int blockSize)
        {
            phase += rateHz * static_cast<float>(blockSize) / sampleRate;
            if (phase >= 1.0f) phase -= 1.0f;
            output = std::sin(phase * 2.0f * 3.14159265f);
        }
    };

    LFO lfoA, lfoB, lfoC;

    // Audio-reactive envelope (separate attack/release per spec: 10ms/100ms)
    float audioEnvSmoothed = 0.0f;
    float audioEnvAttackCoeff = 0.0f;
    float audioEnvReleaseCoeff = 0.0f;

    // Modulation outputs
    float filterAMod = 0.0f;
    float filterBMod = 0.0f;
    float spectralDriftMod = 0.0f;
    float chorusDepthMod = 0.0f;

    double currentSampleRate = 48000.0;
    int currentBlockSize = 32;
};

} // namespace CogDSP
