#include "ModulationEngine.h"
#include <algorithm>

namespace CogDSP {

void ModulationEngine::prepare(double sampleRate, int samplesPerBlock)
{
    currentSampleRate = sampleRate;
    currentBlockSize = std::max(samplesPerBlock, 32);

    // Base rates (irrational ratios)
    lfoA.baseRate = 0.07f;
    lfoB.baseRate = 0.13f;
    lfoC.baseRate = 0.23f;

    // Audio-reactive smoothing: 10ms attack / 100ms release (spec §5.1)
    audioEnvAttackCoeff = 1.0f - std::exp(-1.0f / (static_cast<float>(sampleRate) * 0.01f));
    audioEnvReleaseCoeff = 1.0f - std::exp(-1.0f / (static_cast<float>(sampleRate) * 0.1f));

    reset();
}

void ModulationEngine::reset()
{
    lfoA.phase = 0.0f; lfoA.output = 0.0f;
    lfoB.phase = 0.33f; lfoB.output = 0.0f; // Offset phases
    lfoC.phase = 0.66f; lfoC.output = 0.0f;
    audioEnvSmoothed = 0.0f;
    filterAMod = filterBMod = spectralDriftMod = chorusDepthMod = 0.0f;
}

void ModulationEngine::updateBlock(float evolutionSpeed, float complexity, float reactivity,
                                    float audioEnvelope, float spectralFlux)
{
    // Speed multiplier: 0.1x to 10x
    float speedMult = 0.1f * std::pow(100.0f, evolutionSpeed);

    // Cross-modulation: each LFO modulates the next's rate
    // A -> B -> C -> A ring
    float modDepth = complexity * 2.0f;

    // Compute modulated rates with bounds
    auto boundRate = [](float baseRate, float modOutput, float modDepth, float speedMult) -> float
    {
        float rate = baseRate * speedMult * std::pow(2.0f, modOutput * modDepth);
        float minRate = std::max(baseRate * speedMult * 0.25f, 0.01f);
        float maxRate = std::min(baseRate * speedMult * 4.0f, 20.0f);
        return std::clamp(rate, minRate, maxRate);
    };

    float rateA = boundRate(lfoA.baseRate, lfoC.output, modDepth, speedMult);
    float rateB = boundRate(lfoB.baseRate, lfoA.output, modDepth, speedMult);
    float rateC = boundRate(lfoC.baseRate, lfoB.output, modDepth, speedMult);

    // Advance LFOs
    lfoA.advance(rateA, static_cast<float>(currentSampleRate), currentBlockSize);
    lfoB.advance(rateB, static_cast<float>(currentSampleRate), currentBlockSize);
    lfoC.advance(rateC, static_cast<float>(currentSampleRate), currentBlockSize);

    // Smooth audio envelope with asymmetric attack/release
    float envCoeff = (audioEnvelope > audioEnvSmoothed) ? audioEnvAttackCoeff : audioEnvReleaseCoeff;
    audioEnvSmoothed += envCoeff * (audioEnvelope - audioEnvSmoothed);

    // Compute modulation outputs (in octaves, each clamped ±2)
    float lfoAOct = std::clamp(lfoA.output * 2.0f, -2.0f, 2.0f);
    float lfoBOct = std::clamp(lfoB.output * 2.0f, -2.0f, 2.0f);
    float lfoCOct = std::clamp(lfoC.output * 2.0f, -2.0f, 2.0f);
    float audioOct = std::clamp(audioEnvSmoothed * reactivity * 2.0f, -2.0f, 2.0f);
    float fluxOct = std::clamp(spectralFlux * reactivity * 2.0f, -2.0f, 2.0f);

    // Filter A: LFO A + audio + flux, total clamped ±4
    filterAMod = std::clamp(lfoAOct + audioOct + fluxOct, -4.0f, 4.0f);

    // Filter B: LFO B + audio + flux, total clamped ±4
    filterBMod = std::clamp(lfoBOct + audioOct + fluxOct, -4.0f, 4.0f);

    // Spectral drift: LFO C, subtle (±0.5 of drift range)
    spectralDriftMod = lfoC.output * 0.5f;

    // Chorus depth: LFO A secondary, ±20% of thickness
    chorusDepthMod = lfoA.output * 0.2f;
}

} // namespace CogDSP
