    apvts.getParameter("feedback")->setValueNotifyingHost(apvts.getParameter("feedback")->convertTo0to1(p.feedback));
    apvts.getParameter("width")->setValueNotifyingHost(apvts.getParameter("width")->convertTo0to1(p.width));
    apvts.getParameter("evolutionSpeed")->setValueNotifyingHost(apvts.getParameter("evolutionSpeed")->convertTo0to1(p.evolutionSpeed));
    apvts.getParameter("complexity")->setValueNotifyingHost(apvts.getParameter("complexity")->convertTo0to1(p.complexity));
    apvts.getParameter("reactivity")->setValueNotifyingHost(apvts.getParameter("reactivity")->convertTo0to1(p.reactivity));
