void PresetManager::startMorph(int target, float morphTimeSec, double sampleRate)
{
    if (target < 0 || target >= kNumPresets) return;

    captureCurrentValues(startValues);
    targetValues = getFactoryPresets()[target].values;
    targetPreset = target;
    morphProgress = 0.0f;
    morphActive = true;
    gestureOverrides.clear();

    // Compute increment per block (assuming ~32 sample blocks)
    float blocksForMorph = static_cast<float>(sampleRate * morphTimeSec) / 32.0f;
    morphIncrement = 1.0f / std::max(blocksForMorph, 1.0f);
}

void PresetManager::updateMorph(int samplesPerBlock, double sampleRate)
{
    if (!morphActive) return;

    morphProgress += morphIncrement * (static_cast<float>(samplesPerBlock) / 32.0f);
    if (morphProgress >= 1.0f)
    {
        morphProgress = 1.0f;
        morphActive = false;
        currentPreset = targetPreset;
    }

    interpolateAndApply(morphProgress);
}

void PresetManager::setGestureOverride(const juce::String& paramId)
{
    gestureOverrides.insert(paramId);
}

float PresetManager::lerpParam(float a, float b, float t) const
{
    return a + (b - a) * t;
}

float PresetManager::logLerpFreq(float a, float b, float t) const
{
    float logA = std::log2(std::max(a, 20.0f));
    float logB = std::log2(std::max(b, 20.0f));
    return std::pow(2.0f, logA + (logB - logA) * t);
}

float PresetManager::cosineLerp(float a, float b, float t) const
{
    float ct = 0.5f * (1.0f - std::cos(t * 3.14159265f));
    return a + (b - a) * ct;
}

void PresetManager::interpolateAndApply(float t)
{
    auto setIfNotOverridden = [&](const char* id, float value) {
        if (gestureOverrides.count(id) == 0)
            apvts.getParameter(id)->setValueNotifyingHost(
                apvts.getParameter(id)->convertTo0to1(value));
    };

    setIfNotOverridden("sensitivity",    lerpParam(startValues.sensitivity, targetValues.sensitivity, t));
