2775	    float filterBCutoff = smFilterBCutoff.getNextValue();
2776	    float filterBReso = smFilterBReso.getNextValue();
2777	    float driveAmt = smDrive.getNextValue();
2778	    float tone = smTone.getNextValue();
2779	    float feedbackAmt = smFeedback.getNextValue();
2780	    float width = smWidth.getNextValue();
2781	    float evolution = smEvolution.getNextValue();
2782	    float complexity = smComplexity.getNextValue();
2783	    float reactivity = smReactivity.getNextValue();
2784	    float outputGainDB = smOutputGain.getNextValue();
2785	    float mix = smMix.getNextValue();
2786	    float bypassGain = smBypass.getNextValue();
2787	    bool freeze = smFreeze.getTargetValue() > 0.5f;
2788	
2789	    bool seriesMode = *pFilterRouting > 0.5f;
2790	    auto filterModeA = static_cast<CogDSP::FilterMode>(static_cast<int>(*pFilterAType));
2791	    auto filterModeB = static_cast<CogDSP::FilterMode>(static_cast<int>(*pFilterBType));
2792	
2793	    // === Update modulation engine ===
2794	    float audioEnv = 0.0f;
2795	    {
2796	        auto* L = buffer.getReadPointer(0);
2797	        auto* R = buffer.getReadPointer(1);
2798	        for (int i = 0; i < numSamples; ++i)
2799	            audioEnv += std::fabs(L[i]) + std::fabs(R[i]);
2800	        audioEnv /= static_cast<float>(numSamples * 2);
2801	    }
2802	    modEngine.updateBlock(evolution, complexity, reactivity, audioEnv, detector.getSpectralFlux());
2803	
2804	    // Apply modulation to filter cutoffs (octave-space)
2805	    float modCutoffA = filterACutoff * std::pow(2.0f, modEngine.getFilterAModOctaves());
2806	    modCutoffA = std::clamp(modCutoffA, 20.0f, 20000.0f);
2807	    float modCutoffB = filterBCutoff * std::pow(2.0f, modEngine.getFilterBModOctaves());
2808	    modCutoffB = std::clamp(modCutoffB, 20.0f, 20000.0f);
2809	
2810	    // Apply modulation to spectral drift
2811	    float modDrift = spectralDrift + modEngine.getSpectralDriftMod();
2812	    modDrift = std::clamp(modDrift, -1.0f, 1.0f);
2813	
2814	    // Apply modulation to chorus thickness
2815	    float modThickness = thickness + thickness * modEngine.getChorusDepthMod();
2816	    modThickness = std::clamp(modThickness, 0.0f, 1.0f);
2817	
2818	    // === Step 0: Store dry copy ===
2819	    auto* inputL = buffer.getReadPointer(0);
2820	    auto* inputR = buffer.getReadPointer(1);
2821	    for (int i = 0; i < numSamples; ++i)
2822	    {
2823	        dryCopyDelayL.write(inputL[i]);
2824	        dryCopyDelayR.write(inputR[i]);
2825	    }
2826	
2827	    // === Step 1: Texture/Body Detection ===
2828	    for (int i = 0; i < numSamples; ++i)
2829	        textureCoeffs[i] = detector.processSample(inputL[i], inputR[i], sensitivity);
2830	
2831	    // === Step 2: Split into paths ===
2832	    pathABuffer.setSize(2, numSamples, false, false, true);
2833	    pathBBuffer.setSize(2, numSamples, false, false, true);
2834	
2835	    auto* pathAL = pathABuffer.getWritePointer(0);
2836	    auto* pathAR = pathABuffer.getWritePointer(1);
2837	    auto* pathBL = pathBBuffer.getWritePointer(0);
2838	    auto* pathBR = pathBBuffer.getWritePointer(1);
2839	
2840	    for (int i = 0; i < numSamples; ++i)
2841	    {
2842	        float coeffA = std::max(0.05f, textureCoeffs[i]);
2843	        float coeffB = std::max(0.05f, 1.0f - textureCoeffs[i]);
2844	
2845	        pathAL[i] = inputL[i] * coeffA;
2846	        pathAR[i] = inputR[i] * coeffA;
2847	        pathBL[i] = inputL[i] * coeffB;
2848	        pathBR[i] = inputR[i] * coeffB;
2849	    }
2850	
2851	    // === Step 3: Path A — Waveshaper + latency compensation ===
2852	    waveshaper.process(pathABuffer, textureCoeffs.data(), textureDrive);
2853	
2854	    // === Step 4: Path B — Spectral Drone Engine + Chorus ===
2855	    spectralEngine.process(pathBBuffer, pathBBuffer, droneDensity, modDrift, freeze);
2856	    chorus.process(pathBBuffer, modThickness);
2857	
2858	    // === Step 5: Merge paths ===
2859	    auto* outL = buffer.getWritePointer(0);
2860	    auto* outR = buffer.getWritePointer(1);
2861	
2862	    float balCosine = std::cos(pathBalance * 3.14159265f * 0.5f);
2863	    float balSine = std::sin(pathBalance * 3.14159265f * 0.5f);
2864	
2865	    for (int i = 0; i < numSamples; ++i)
2866	    {
2867	        // Read latency-compensated Path A from delay
2868	        float aL = waveshaper.readDelayedL(spectralLatencySamples);
2869	        float aR = waveshaper.readDelayedR(spectralLatencySamples);
2870	
2871	        float bL = pathBL[i];
2872	        float bR = pathBR[i];
2873	
2874	        // Equal-power crossfade
2875	        float mergedL = aL * balCosine + bL * balSine;
2876	        float mergedR = aR * balCosine + bR * balSine;
2877	
2878	        // Add feedback return
2879	        if (feedbackBuffer.getNumSamples() > i)
2880	        {
2881	            mergedL += feedbackBuffer.getSample(0, i);
2882	            mergedR += feedbackBuffer.getSample(1, i);
2883	        }
2884	
2885	        outL[i] = mergedL;
2886	        outR[i] = mergedR;
2887	    }
2888	
2889	    // === Step 6: Self-resonating filters ===
2890	    filters.process(buffer, modCutoffA, filterAReso, filterModeA,
2891	                    modCutoffB, filterBReso, filterModeB, seriesMode);
2892	
2893	    // === Step 7: Drive circuit ===
2894	    drive.process(buffer, driveAmt, tone);
2895	
2896	    // === Step 8: Feedback tap → DC block → soft-clip → attenuate ===
2897	    feedbackBuffer.setSize(2, numSamples, false, false, true);
2898	    if (feedbackAmt > 0.001f)
2899	    {
2900	        auto* fbL = feedbackBuffer.getWritePointer(0);
2901	        auto* fbR = feedbackBuffer.getWritePointer(1);
2902	        for (int i = 0; i < numSamples; ++i)
2903	        {
2904	            float dcL = feedbackDCBlockerL.process(outL[i]);
2905	            float dcR = feedbackDCBlockerR.process(outR[i]);
2906	            fbL[i] = CogDSP::fastTanh(dcL) * feedbackAmt;
2907	            fbR[i] = CogDSP::fastTanh(dcR) * feedbackAmt;
2908	        }
2909	    }
2910	    else
2911	    {
2912	        feedbackBuffer.clear();
2913	    }
2914	
2915	    // === Step 9: Stereo widener ===
2916	    widener.process(buffer, width);
2917	
2918	    // === Step 10: Final limiter (tanh) ===
2919	    for (int i = 0; i < numSamples; ++i)
2920	    {
2921	        outL[i] = CogDSP::fastTanh(outL[i]);
2922	        outR[i] = CogDSP::fastTanh(outR[i]);
2923	    }
2924	
2925	    // === Step 11: Output gain ===
2926	    float outputGainLinear = std::pow(10.0f, outputGainDB / 20.0f);
2927	    buffer.applyGain(outputGainLinear);
2928	
2929	    // === Step 12: Dry/wet mix ===
2930	    float wetGain = std::sin(mix * 3.14159265f * 0.5f);
2931	    float dryGain = std::cos(mix * 3.14159265f * 0.5f);
2932	
2933	    for (int i = 0; i < numSamples; ++i)
2934	    {
2935	        float dryL = dryCopyDelayL.read(spectralLatencySamples);
2936	        float dryR = dryCopyDelayR.read(spectralLatencySamples);
2937	
2938	        outL[i] = outL[i] * wetGain + dryL * dryGain;
2939	        outR[i] = outR[i] * wetGain + dryR * dryGain;
2940	    }
2941	
2942	    // === Step 13: Bypass blend ===
2943	    if (bypassGain > 0.001f)
2944	    {
2945	        for (int i = 0; i < numSamples; ++i)
2946	        {
2947	            float dryL = dryCopyDelayL.read(spectralLatencySamples);
2948	            float dryR = dryCopyDelayR.read(spectralLatencySamples);
2949	            outL[i] = outL[i] * (1.0f - bypassGain) + dryL * bypassGain;
2950	            outR[i] = outR[i] * (1.0f - bypassGain) + dryR * bypassGain;
2951	        }
2952	    }
2953	}
