void CogVSTProcessor::prepareToPlay(double sampleRate, int samplesPerBlock)
{
    currentSampleRate = sampleRate;
    spectralLatencySamples = 2048; // Always 2048 at internal 48kHz rate

    // DSP modules
    detector.prepare(sampleRate, samplesPerBlock);
    waveshaper.prepare(sampleRate, spectralLatencySamples);
    spectralEngine.prepare(sampleRate, samplesPerBlock);
    chorus.prepare(sampleRate, samplesPerBlock);
    filters.prepare(sampleRate);
    drive.prepare(sampleRate);
    widener.prepare(sampleRate);
    modEngine.prepare(sampleRate, samplesPerBlock);

    // Feedback
    feedbackDCBlockerL.prepare(sampleRate);
    feedbackDCBlockerR.prepare(sampleRate);
    feedbackBuffer.setSize(2, samplesPerBlock);
    feedbackBuffer.clear();

    // Dry copy delay
    dryCopyDelayL.prepare(spectralLatencySamples + 64);
    dryCopyDelayR.prepare(spectralLatencySamples + 64);

    // Temp buffers
    pathABuffer.setSize(2, samplesPerBlock);
    pathBBuffer.setSize(2, samplesPerBlock);
    textureCoeffs.resize(samplesPerBlock, 0.0f);

    // SmoothedValues — 20ms ramp for continuous, 5ms for booleans
    auto initSmooth = [&](juce::SmoothedValue<float>& sm, float val, float rampSec = 0.02f) {
        sm.reset(sampleRate, rampSec);
        sm.setCurrentAndTargetValue(val);
    };

    initSmooth(smSensitivity,   *pSensitivity);
    initSmooth(smPathBalance,   *pPathBalance);
    initSmooth(smTextureDrive,  *pTextureDrive);
    initSmooth(smDroneDensity,  *pDroneDensity);
    initSmooth(smSpectralDrift, *pSpectralDrift);
    initSmooth(smThickness,     *pThickness);
    initSmooth(smFilterACutoff, *pFilterACutoff);
    initSmooth(smFilterAReso,   *pFilterAReso);
    initSmooth(smFilterBCutoff, *pFilterBCutoff);
    initSmooth(smFilterBReso,   *pFilterBReso);
    initSmooth(smDrive,         *pDrive);
    initSmooth(smTone,          *pTone);
    initSmooth(smFeedback,      *pFeedback);
    initSmooth(smWidth,         *pWidth);
    initSmooth(smEvolution,     *pEvolution);
    initSmooth(smComplexity,    *pComplexity);
    initSmooth(smReactivity,    *pReactivity);
    initSmooth(smOutputGain,    *pOutputGain);
    initSmooth(smMix,           *pMix);
    initSmooth(smBypass,        *pBypass > 0.5f ? 1.0f : 0.0f, 0.005f);
    initSmooth(smFreeze,        *pFreeze > 0.5f ? 1.0f : 0.0f, 0.005f);

    // Report latency
    setLatencySamples(spectralLatencySamples);
}

