void CogVSTProcessor::processBlock(juce::AudioBuffer<float>& buffer, juce::MidiBuffer&)
{
    juce::ScopedNoDenormals noDenormals;

    auto totalNumInputChannels  = getTotalNumInputChannels();
    auto totalNumOutputChannels = getTotalNumOutputChannels();
    int numSamples = buffer.getNumSamples();

    // Clear unused output channels
    for (auto i = totalNumInputChannels; i < totalNumOutputChannels; ++i)
        buffer.clear(i, 0, numSamples);

    if (buffer.getNumChannels() < 2) return;

    // === Update SmoothedValue targets (once per block) ===
    smSensitivity.setTargetValue(*pSensitivity);
    smPathBalance.setTargetValue(*pPathBalance);
    smTextureDrive.setTargetValue(*pTextureDrive);
    smDroneDensity.setTargetValue(*pDroneDensity);
    smSpectralDrift.setTargetValue(*pSpectralDrift);
    smThickness.setTargetValue(*pThickness);
    smFilterACutoff.setTargetValue(*pFilterACutoff);
    smFilterAReso.setTargetValue(*pFilterAReso);
    smFilterBCutoff.setTargetValue(*pFilterBCutoff);
    smFilterBReso.setTargetValue(*pFilterBReso);
    smDrive.setTargetValue(*pDrive);
    smTone.setTargetValue(*pTone);
    smFeedback.setTargetValue(*pFeedback);
    smWidth.setTargetValue(*pWidth);
    smEvolution.setTargetValue(*pEvolution);
    smComplexity.setTargetValue(*pComplexity);
    smReactivity.setTargetValue(*pReactivity);
    smOutputGain.setTargetValue(*pOutputGain);
    smMix.setTargetValue(*pMix);
    smBypass.setTargetValue(*pBypass > 0.5f ? 1.0f : 0.0f);
    smFreeze.setTargetValue(*pFreeze > 0.5f ? 1.0f : 0.0f);

    // Update preset morph
    presetManager.updateMorph(numSamples, currentSampleRate);

    // Get block-level parameter values
    float sensitivity = smSensitivity.getNextValue();
    float pathBalance = smPathBalance.getNextValue();
    float textureDrive = smTextureDrive.getNextValue();
    float droneDensity = smDroneDensity.getNextValue();
    float spectralDrift = smSpectralDrift.getNextValue();
    float thickness = smThickness.getNextValue();
    float filterACutoff = smFilterACutoff.getNextValue();
    float filterAReso = smFilterAReso.getNextValue();
    float filterBCutoff = smFilterBCutoff.getNextValue();
    float filterBReso = smFilterBReso.getNextValue();
    float driveAmt = smDrive.getNextValue();
    float tone = smTone.getNextValue();
    float feedbackAmt = smFeedback.getNextValue();
    float width = smWidth.getNextValue();
    float evolution = smEvolution.getNextValue();
    float complexity = smComplexity.getNextValue();
    float reactivity = smReactivity.getNextValue();
    float outputGainDB = smOutputGain.getNextValue();
    float mix = smMix.getNextValue();
    float bypassGain = smBypass.getNextValue();
    bool freeze = smFreeze.getTargetValue() > 0.5f;

    bool seriesMode = *pFilterRouting > 0.5f;
    auto filterModeA = static_cast<CogDSP::FilterMode>(static_cast<int>(*pFilterAType));
    auto filterModeB = static_cast<CogDSP::FilterMode>(static_cast<int>(*pFilterBType));

    // === Update modulation engine ===
    float audioEnv = 0.0f;
    {
        auto* L = buffer.getReadPointer(0);
        auto* R = buffer.getReadPointer(1);
        for (int i = 0; i < numSamples; ++i)
            audioEnv += std::fabs(L[i]) + std::fabs(R[i]);
        audioEnv /= static_cast<float>(numSamples * 2);
    }
    modEngine.updateBlock(evolution, complexity, reactivity, audioEnv, detector.getSpectralFlux());

    // Apply modulation to filter cutoffs (octave-space)
    float modCutoffA = filterACutoff * std::pow(2.0f, modEngine.getFilterAModOctaves());
    modCutoffA = std::clamp(modCutoffA, 20.0f, 20000.0f);
    float modCutoffB = filterBCutoff * std::pow(2.0f, modEngine.getFilterBModOctaves());
    modCutoffB = std::clamp(modCutoffB, 20.0f, 20000.0f);

    // Apply modulation to spectral drift
    float modDrift = spectralDrift + modEngine.getSpectralDriftMod();
    modDrift = std::clamp(modDrift, -1.0f, 1.0f);

    // Apply modulation to chorus thickness
    float modThickness = thickness + thickness * modEngine.getChorusDepthMod();
    modThickness = std::clamp(modThickness, 0.0f, 1.0f);

    // === Step 0: Store dry copy ===
    auto* inputL = buffer.getReadPointer(0);
    auto* inputR = buffer.getReadPointer(1);
    for (int i = 0; i < numSamples; ++i)
    {
        dryCopyDelayL.write(inputL[i]);
        dryCopyDelayR.write(inputR[i]);
    }

    // === Step 1: Texture/Body Detection ===
    for (int i = 0; i < numSamples; ++i)
        textureCoeffs[i] = detector.processSample(inputL[i], inputR[i], sensitivity);

    // === Step 2: Split into paths ===
    pathABuffer.setSize(2, numSamples, false, false, true);
    pathBBuffer.setSize(2, numSamples, false, false, true);

    auto* pathAL = pathABuffer.getWritePointer(0);
    auto* pathAR = pathABuffer.getWritePointer(1);
    auto* pathBL = pathBBuffer.getWritePointer(0);
    auto* pathBR = pathBBuffer.getWritePointer(1);

    for (int i = 0; i < numSamples; ++i)
    {
        float coeffA = std::max(0.05f, textureCoeffs[i]);
        float coeffB = std::max(0.05f, 1.0f - textureCoeffs[i]);

        pathAL[i] = inputL[i] * coeffA;
        pathAR[i] = inputR[i] * coeffA;
        pathBL[i] = inputL[i] * coeffB;
        pathBR[i] = inputR[i] * coeffB;
    }

    // === Step 3: Path A — Waveshaper + latency compensation ===
    waveshaper.process(pathABuffer, textureCoeffs.data(), textureDrive);

    // === Step 4: Path B — Spectral Drone Engine + Chorus ===
    spectralEngine.process(pathBBuffer, pathBBuffer, droneDensity, modDrift, freeze);
    chorus.process(pathBBuffer, modThickness);

    // === Step 5: Merge paths ===
    auto* outL = buffer.getWritePointer(0);
    auto* outR = buffer.getWritePointer(1);

    float balCosine = std::cos(pathBalance * 3.14159265f * 0.5f);
    float balSine = std::sin(pathBalance * 3.14159265f * 0.5f);

    for (int i = 0; i < numSamples; ++i)
    {
        // Read latency-compensated Path A from delay
        float aL = waveshaper.readDelayedL(spectralLatencySamples);
        float aR = waveshaper.readDelayedR(spectralLatencySamples);

        float bL = pathBL[i];
        float bR = pathBR[i];

        // Equal-power crossfade
        float mergedL = aL * balCosine + bL * balSine;
        float mergedR = aR * balCosine + bR * balSine;

        // Add feedback return
        if (feedbackBuffer.getNumSamples() > i)
        {
            mergedL += feedbackBuffer.getSample(0, i);
            mergedR += feedbackBuffer.getSample(1, i);
        }

        outL[i] = mergedL;
        outR[i] = mergedR;
    }

    // === Step 6: Self-resonating filters ===
    filters.process(buffer, modCutoffA, filterAReso, filterModeA,
                    modCutoffB, filterBReso, filterModeB, seriesMode);

    // === Step 7: Drive circuit ===
    drive.process(buffer, driveAmt, tone);

    // === Step 8: Feedback tap → DC block → soft-clip → attenuate ===
    feedbackBuffer.setSize(2, numSamples, false, false, true);
    if (feedbackAmt > 0.001f)
    {
        auto* fbL = feedbackBuffer.getWritePointer(0);
        auto* fbR = feedbackBuffer.getWritePointer(1);
        for (int i = 0; i < numSamples; ++i)
        {
            float dcL = feedbackDCBlockerL.process(outL[i]);
            float dcR = feedbackDCBlockerR.process(outR[i]);
            fbL[i] = CogDSP::fastTanh(dcL) * feedbackAmt;
            fbR[i] = CogDSP::fastTanh(dcR) * feedbackAmt;
        }
    }
    else
    {
        feedbackBuffer.clear();
    }

    // === Step 9: Stereo widener ===
    widener.process(buffer, width);

    // === Step 10: Final limiter (tanh) ===
    for (int i = 0; i < numSamples; ++i)
    {
        outL[i] = CogDSP::fastTanh(outL[i]);
        outR[i] = CogDSP::fastTanh(outR[i]);
    }

    // === Step 11: Output gain ===
    float outputGainLinear = std::pow(10.0f, outputGainDB / 20.0f);
    buffer.applyGain(outputGainLinear);

    // === Step 12: Dry/wet mix ===
    float wetGain = std::sin(mix * 3.14159265f * 0.5f);
    float dryGain = std::cos(mix * 3.14159265f * 0.5f);

    for (int i = 0; i < numSamples; ++i)
    {
        float dryL = dryCopyDelayL.read(spectralLatencySamples);
        float dryR = dryCopyDelayR.read(spectralLatencySamples);

        outL[i] = outL[i] * wetGain + dryL * dryGain;
        outR[i] = outR[i] * wetGain + dryR * dryGain;
    }

    // === Step 13: Bypass blend ===
    if (bypassGain > 0.001f)
    {
        for (int i = 0; i < numSamples; ++i)
        {
            float dryL = dryCopyDelayL.read(spectralLatencySamples);
            float dryR = dryCopyDelayR.read(spectralLatencySamples);
            outL[i] = outL[i] * (1.0f - bypassGain) + dryL * bypassGain;
            outR[i] = outR[i] * (1.0f - bypassGain) + dryR * bypassGain;
        }
    }
}
