void CogLookAndFeel::drawRotarySlider(juce::Graphics& g, int x, int y, int width, int height,
                                       float sliderPos, float startAngle, float endAngle,
                                       juce::Slider& slider)
{
    auto bounds = juce::Rectangle<int>(x, y, width, height).toFloat().reduced(4.0f);
    auto radius = juce::jmin(bounds.getWidth(), bounds.getHeight()) / 2.0f;
    auto centre = bounds.getCentre();
    auto angle = startAngle + sliderPos * (endAngle - startAngle);

    // Track
    juce::Path track;
    track.addCentredArc(centre.x, centre.y, radius, radius, 0.0f, startAngle, endAngle, true);
    g.setColour(juce::Colour(kKnobTrack));
    g.strokePath(track, juce::PathStrokeType(3.0f, juce::PathStrokeType::curved));

    // Active arc
    juce::Path arc;
    arc.addCentredArc(centre.x, centre.y, radius, radius, 0.0f, startAngle, angle, true);
    g.setColour(juce::Colour(kNeonCyan));
    g.strokePath(arc, juce::PathStrokeType(3.0f, juce::PathStrokeType::curved));

    // Thumb
    juce::Point<float> thumbPoint(centre.x + (radius - 2.0f) * std::cos(angle - juce::MathConstants<float>::halfPi),
                                   centre.y + (radius - 2.0f) * std::sin(angle - juce::MathConstants<float>::halfPi));
    g.setColour(juce::Colour(kCosmicGold));
    g.fillEllipse(juce::Rectangle<float>(6.0f, 6.0f).withCentre(thumbPoint));
}
