│   │   ├── FastMath.h
│   │   ├── DCBlocker.h
│   │   ├── DelayLine.h
│   │   ├── TextureBodyDetector.h/cpp
│   │   ├── Waveshaper.h/cpp
│   │   ├── SpectralDroneEngine.h/cpp
│   │   ├── ChorusEnsemble.h/cpp
│   │   ├── ResonantFilter.h/cpp
│   │   ├── DriveCircuit.h/cpp
│   │   ├── StereoWidener.h/cpp
│   │   ├── ModulationEngine.h/cpp
│   ├── Presets/
│   │   ├── PresetData.h
│   │   ├── PresetManager.h/cpp
│   ├── GUI/
│   │   ├── CogLookAndFeel.h/cpp
