    float rmsEnvelopeR = 0.0f;
    // NOT a single shared rmsEnvelope
};
```

**Fix #12 (Moderate):** Tone coefficients computed once per block:
```cpp
void process(juce::AudioBuffer<float>& buffer, float drive, float tone) {
    // Pre-compute tone coefficients BEFORE the sample loop
    float toneAmount = (tone - 0.5f) * 2.0f;
    float cutoff = 1000.0f;
    float rc = 1.0f / (2.0f * 3.14159265f * cutoff);
    float dt = 1.0f / static_cast<float>(currentSampleRate);
    float alpha = dt / (rc + dt);
    float gainHigh = std::pow(10.0f, toneAmount * 6.0f / 20.0f);

    for (int i = 0; i < numSamples; ++i) {
        // Use pre-computed alpha, gainHigh in loop
    }
}
```

**Fix #13 (Moderate):** Remove unused toneCoeff parameter:
```cpp
float processSample(float input, float drive); // NOT float processSample(float input, float drive, float toneCoeff)
```

### Task 9: StereoWidener

**Fix #10 (Important):** Always process crossover filters:
```cpp
void process(juce::AudioBuffer<float>& buffer, float width) {
    // Always process through crossover filters (prevents click on enable)
    for (int i = 0; i < numSamples; ++i) {
        float lowL = processLR2LP(lpStateL, L);
        float lowR = processLR2LP(lpStateR, R);
        float highL = processLR2HP(hpStateL, L);
        float highR = processLR2HP(hpStateR, R);

        if (width < 0.001f) {
            // Skip only M/S widening, still update filter state
            left[i] = lowL + highL;
            right[i] = lowR + highR;
        } else {
            // M/S widening with crossover
            float lowMono = (lowL + lowR) * 0.5f;
            float mid = (highL + highR) * 0.5f;
            float side = (highL - highR) * 0.5f * (1.0f + width * 2.0f);
            left[i] = lowMono + mid + side;
            right[i] = lowMono + mid - side;
        }
    }
}
```

### Task 10: ModulationEngine

**Fix #7 (Important):** Separate attack/release coefficients for audio envelope:
```cpp
struct AudioEnvelope {
    float value = 0.0f;
    float attackCoeff = 0.0f;   // 10ms
    float releaseCoeff = 0.0f;  // 100ms

    void prepare(double sampleRate) {
        attackCoeff = 1.0f - std::exp(-1.0f / (sampleRate * 0.01f));
        releaseCoeff = 1.0f - std::exp(-1.0f / (sampleRate * 0.1f));
    }

    float process(float input) {
        float coeff = (input > value) ? attackCoeff : releaseCoeff;
        value += coeff * (input - value);
        return value;
    }
};
```

### Task 11: PresetManager

**Fix #9 (Important):** Thread-safe gesture overrides using atomic flags:
```cpp
class PresetManager {
    static constexpr int kNumMorphableParams = 22;
    std::atomic<bool> gestureOverrides[kNumMorphableParams] = {};

    void setGestureOverride(const juce::String& paramId) {
        int idx = paramIdToIndex(paramId);
        if (idx >= 0) gestureOverrides[idx].store(true);
    }

    bool isOverridden(int idx) const {
        return gestureOverrides[idx].load();
    }
};
```

### Task 12: PluginProcessor — APVTS & Prepare

**Fix #14 (Moderate):** Pre-allocate buffers in prepareToPlay:
```cpp
void prepareToPlay(double sampleRate, int samplesPerBlock) {
    // Pre-allocate for worst-case (2x samplesPerBlock to be safe)
    int maxSamples = samplesPerBlock * 2;
    pathABuffer.setSize(2, maxSamples);
