    dryCopyDelayR.prepare(maxSamples + spectralLatencySamples);
}
```

**Fix #3 (Critical):** Correct latency computation:
```cpp
void prepareToPlay(double sampleRate, int samplesPerBlock) {
    // Compute decimation factor
    int decimationFactor = 1;
    if (sampleRate > 96000.0) decimationFactor = 4;
    else if (sampleRate > 48000.0) decimationFactor = 2;

    spectralEngine.prepare(sampleRate, samplesPerBlock, decimationFactor);
