    }
} else {
    pathBalance = smPathBalance.getCurrentValue();  // Block-constant
    for (int i = 0; i < numSamples; ++i) {
        // ... use pathBalance (same for all samples)
    }
}
```

**Fix #19 (Spec):** Conditional spectral engine bypass:
```cpp
bool spectralActive = (droneDensity > 0.001f) || freeze || (std::fabs(spectralDrift) > 0.001f);
