void process(juce::AudioBuffer<float>& buffer, float width) {
    // Always process through crossover filters (prevents click on enable)
    for (int i = 0; i < numSamples; ++i) {
        float lowL = processLR2LP(lpStateL, L);
        float lowR = processLR2LP(lpStateR, R);
        float highL = processLR2HP(hpStateL, L);
        float highR = processLR2HP(hpStateR, R);

        if (width < 0.001f) {
            // Skip only M/S widening, still update filter state
            left[i] = lowL + highL;
            right[i] = lowR + highR;
        } else {
            // M/S widening with crossover
            float lowMono = (lowL + lowR) * 0.5f;
            float mid = (highL + highR) * 0.5f;
            float side = (highL - highR) * 0.5f * (1.0f + width * 2.0f);
            left[i] = lowMono + mid + side;
            right[i] = lowMono + mid - side;
        }
    }
}
