#pragma once
#include <cmath>

namespace CogDSP {

// Padé approximant tanh — error < 0.1% for |x| < 4
// For |x| >= 4, returns ±1.0
inline float fastTanh(float x)
{
    if (x > 4.0f) return 1.0f;
    if (x < -4.0f) return -1.0f;
    float x2 = x * x;
    return x * (27.0f + x2) / (27.0f + 9.0f * x2);
}

// Fast atan — polynomial for |x| < 2.5, asymptotic beyond
inline float fastAtan(float x)
{
    if (x > 2.5f) return 1.5707963f - 1.0f / x;    // pi/2 - 1/x
    if (x < -2.5f) return -1.5707963f - 1.0f / x;
    float x2 = x * x;
    return x * (1.0f + 0.28125f * x2) / (1.0f + 0.5625f * x2 + 0.078125f * x2 * x2);
}

// Fast exp(-x*x) — rational approximation
inline float fastGaussian(float x)
{
    float x2 = x * x;
    return 1.0f / (1.0f + x2 * (1.0f + x2 * 0.5f));
}

} // namespace CogDSP
EOF

