#pragma once

namespace CogDSP {

class DCBlocker
{
public:
    void prepare(double sampleRate)
    {
        // 5Hz HPF cutoff, scaled by sample rate
        R = 1.0f - static_cast<float>(2.0 * 3.14159265358979 * 5.0 / sampleRate);
    }

    void reset()
    {
        xPrev = 0.0f;
        yPrev = 0.0f;
    }

    float process(float x)
    {
        float y = x - xPrev + R * yPrev;
        xPrev = x;
        yPrev = y;
        return y;
    }

private:
    float R = 0.99935f;
    float xPrev = 0.0f;
    float yPrev = 0.0f;
};

} // namespace CogDSP
