#pragma once
#include <vector>
#include <algorithm>
#include <cstring>

namespace CogDSP {

class DelayLine
{
public:
    void prepare(int maxSamples)
    {
        // Round up to power of 2 for & mask wrapping
        int size = 1;
        while (size < maxSamples + 1) size <<= 1;
        buffer.resize(size, 0.0f);
        mask = size - 1;
        writePos = 0;
    }

    void reset()
    {
        std::fill(buffer.begin(), buffer.end(), 0.0f);
        writePos = 0;
    }

    void write(float sample)
    {
        buffer[writePos & mask] = sample;
        ++writePos;
    }

    // Read at integer delay (samples ago)
    float read(int delaySamples) const
    {
        return buffer[(writePos - delaySamples) & mask];
    }

    // FIX #1: Read with additional offset for per-sample delay reads
    // Used when walking backwards through delay buffer in merge loop
    float readDelayed(int baseDelay, int sampleOffset) const
    {
        return buffer[(writePos - baseDelay - sampleOffset) & mask];
    }

    // Read with fractional delay (linear interpolation)
    float readInterp(float delaySamples) const
    {
        int d0 = static_cast<int>(delaySamples);
        float frac = delaySamples - static_cast<float>(d0);
        float s0 = buffer[(writePos - d0) & mask];
        float s1 = buffer[(writePos - d0 - 1) & mask];
        return s0 + frac * (s1 - s0);
    }

private:
    std::vector<float> buffer;
    int mask = 0;
    int writePos = 0;
};

} // namespace CogDSP
EOF
